function eventStateDisplayLabel(state) {
  const value = String(state || 'New');
  if (value === 'Pending Closure' && !isAdminUser()) return 'Closed';
  return value === 'Added' ? 'New' : value;
}

function playWorkflowTone(kind = 'success') {
  try {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return;
    const context = window.__showbaseAudioContext || new AudioContextClass();
    window.__showbaseAudioContext = context;
    const start = context.currentTime;
    const notes = kind === 'error'
      ? [{ frequency: 220, offset: 0, duration: 0.13 }, { frequency: 165, offset: 0.13, duration: 0.2 }]
      : [{ frequency: 660, offset: 0, duration: 0.08 }, { frequency: 880, offset: 0.08, duration: 0.12 }];
    notes.forEach(note => {
      const oscillator = context.createOscillator();
      const gain = context.createGain();
      oscillator.type = kind === 'error' ? 'square' : 'sine';
      oscillator.frequency.setValueAtTime(note.frequency, start + note.offset);
      gain.gain.setValueAtTime(0.0001, start + note.offset);
      gain.gain.exponentialRampToValueAtTime(0.12, start + note.offset + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.0001, start + note.offset + note.duration);
      oscillator.connect(gain);
      gain.connect(context.destination);
      oscillator.start(start + note.offset);
      oscillator.stop(start + note.offset + note.duration);
    });
  } catch (error) {
    // Audio feedback is best-effort and must never interrupt scanning.
  }
}

function clearWorkflowScanInput(input, processedValue) {
  if (!input) return;
  if (normalizeScannedIdentifier(input.value) === normalizeScannedIdentifier(processedValue)) {
    input.value = '';
  }
  input.focus({ preventScroll: true });
}

function isAdminUser() {
  return !!(currentUser && currentUser.isAdmin);
}

function currentUserRole() {
  return String(currentUser?.role || (currentUser?.isSuperAdmin || currentUser?.isAdmin ? 'admin' : 'user')).toLowerCase();
}

function isPlatformAdminUser() {
  return !!(currentUser && currentUser.isSuperAdmin);
}

function isSuperAdminUser() {
  return isPlatformAdminUser();
}

function canCurrentUserManageRoles() {
  return !!(currentUser && (currentUser.canManageRoles || currentUserRole() === 'admin'));
}

function canCurrentUserManageUsers() {
  return !!(
    currentUser
    && (
      currentUser.canManageUsers
      || ['owner', 'admin', 'manager'].includes(currentUserRole())
    )
  );
}

function canCurrentUserManageUser(user) {
  if (!canCurrentUserManageUsers() || !user) return false;
  if (isPlatformAdminUser()) return true;
  const targetRole = String(
    user.role || (user.isSuperAdmin || user.isAdmin ? 'admin' : 'user')
  ).toLowerCase();
  if (currentUserRole() === 'admin') return targetRole !== 'owner';
  return currentUserRole() === 'manager' && ['manager', 'user'].includes(targetRole);
}

function currentUserHasSalesAccess() {
  return !!(currentUser && (isPlatformAdminUser() || currentUser.hasSalesAccess || currentUser.isSales));
}

function userRoleLabel(role = currentUserRole()) {
  const value = String(role || 'user').toLowerCase();
  return ({
    owner: 'Owner',
    admin: 'Admin',
    manager: 'Manager',
    user: 'User'
  })[value] || 'User';
}

function userInitials(username) {
  const parts = String(username || 'User').trim().split(/\s+/).filter(Boolean);
  const source = parts.length > 1 ? parts.slice(0, 2) : [parts[0] || 'U'];
  return source.map(part => part[0] || '').join('').toUpperCase().slice(0, 2) || 'U';
}

function roleBadgeMarkup(role, extraClass = '') {
  const rawRole = String(role || '').toLowerCase();
  const safeRole = ['owner', 'admin', 'manager', 'user'].includes(rawRole)
    ? String(role || '').toLowerCase()
    : 'user';
  return `<span class="user-role-badge user-role-badge-${safeRole} ${extraClass}">${escapeHtml(userRoleLabel(safeRole))}</span>`;
}

