function applyPermissionUi() {
  const adminOnlySelectors = [
    ".admin-only",
    "[data-admin-only='true']"
  ];

  adminOnlySelectors.forEach(selector => {
    document.querySelectorAll(selector).forEach(el => {
      el.style.display = isAdminUser() ? (el.dataset.adminDisplay || 'block') : 'none';
    });
  });

  document.querySelectorAll(".platform-admin-only, [data-platform-admin-only='true'], .super-admin-only, [data-super-admin-only='true']").forEach(el => {
    el.style.display = isPlatformAdminUser() ? (el.dataset.platformAdminDisplay || el.dataset.superAdminDisplay || el.dataset.adminDisplay || 'block') : 'none';
  });

  document.querySelectorAll(".sales-only, [data-sales-only='true']").forEach(el => {
    el.style.display = currentUserHasSalesAccess() ? (el.dataset.salesDisplay || 'block') : 'none';
  });

  document.querySelectorAll(".log-access-only, [data-log-access-only='true']").forEach(el => {
    el.style.display = canCurrentUserManageRoles() ? (el.dataset.logAccessDisplay || 'block') : 'none';
  });

  // Older hard-coded create buttons do not all have a class, so hide them by onclick.
  document.querySelectorAll('button').forEach(button => {
    if (
      button.getAttribute('onclick') === "openModal('addEventModal')" ||
      button.getAttribute('onclick') === "openAddEventModal()" ||
      button.getAttribute('onclick') === "openModal('addAssetModal')"
    ) {
      button.style.display = isAdminUser()
        ? (button.dataset.adminDisplay || '')
        : 'none';
    }
  });
}

