function getAssetIdentifierForApi(asset) {
  return asset?.internalId || asset?.bulkId || asset?.id || '';
}

function getAssetByApiIdentifier(assetId, assetList = assets) {
  const normalized = String(assetId || '').trim();
  if (!normalized || !Array.isArray(assetList)) return null;
  const lower = normalized.toLowerCase();
  return assetList.find(asset => {
    if (!asset) return false;
    return [
      getAssetIdentifierForApi(asset),
      asset.id,
      asset.internalId,
      asset.bulkId,
      asset.displayId
    ].some(value => String(value || '').trim().toLowerCase() === lower);
  }) || null;
}

function assetMaintenanceDisplayId(asset) {
  if (!asset) return '';
  if (asset.isBulk) return getAssetIdentifierForApi(asset) || 'Bulk Item';
  return asset.id || getAssetIdentifierForApi(asset);
}

function assetMaintenanceDisplayName(asset) {
  if (!asset) return '';
  const id = assetMaintenanceDisplayId(asset);
  const name = [asset.brand, asset.model, asset.description]
    .map(value => String(value || '').trim())
    .filter(Boolean)
    .join(' ');
  return asset.isBulk ? `${name || 'Bulk Item'} (${id})` : (id || name);
}

function normalizeAssetPurchaseDateValue(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';

  const isoMatch = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (isoMatch) return raw;

  const slashMatch = raw.match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);
  if (slashMatch) {
    return `${slashMatch[1]}-${slashMatch[2].padStart(2, '0')}-${slashMatch[3].padStart(2, '0')}`;
  }

  const compactMatch = raw.match(/^(\d{4})(\d{2})(\d{2})$/);
  if (compactMatch) return `${compactMatch[1]}-${compactMatch[2]}-${compactMatch[3]}`;

  return raw;
}

function formatAssetPurchaseDate(value) {
  const normalized = normalizeAssetPurchaseDateValue(value);
  const match = normalized.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return normalized || '-';
  return `${match[1]}/${match[2]}/${match[3]}`;
}

function isAssetDegraded(asset) {
  if (!asset) return false;
  if (asset.isBulk) return !!asset.isDegraded;
  return !!(asset.isDegraded || asset.status === 'degraded');
}

function maintenanceLogMarksStatus(log, status, action = 'marked') {
  const record = normalizeMaintenanceLogRecord(log);
  const targetStatus = String(status || '').trim().toLowerCase();
  const targetAction = String(action || '').trim().toLowerCase();
  return (record.changes || []).some(change =>
    String(change.kind || '').trim().toLowerCase() === targetStatus &&
    String(change.action || '').trim().toLowerCase() === targetAction
  );
}

function cleanDegradedReasonText(value, maxLength = 240) {
  const reason = String(value || '').replace(/\s+/g, ' ').trim();
  if (!reason) return '';
  return reason.length > maxLength ? `${reason.slice(0, maxLength - 1).trim()}...` : reason;
}

function getAssetDegradedReasons(asset, limit = 3) {
  if (!asset) return [];

  const directReasons = Array.isArray(asset.degradedReasons)
    ? asset.degradedReasons.map(reason => cleanDegradedReasonText(reason)).filter(Boolean)
    : [];
  if (directReasons.length) return directReasons.slice(0, limit);

  let activeReason = '';
  getMaintenanceLogRecords(asset).forEach(log => {
    if (maintenanceLogMarksStatus(log, 'degraded', 'marked')) {
      activeReason = cleanDegradedReasonText(log.description);
    }
    if (maintenanceLogMarksStatus(log, 'degraded', 'cleared')) {
      activeReason = '';
    }
  });

  return activeReason ? [activeReason] : [];
}

function degradedReasonMessage(reasons) {
  const cleanReasons = (reasons || []).map(reason => cleanDegradedReasonText(reason)).filter(Boolean);
  if (!cleanReasons.length) return '';
  return cleanReasons.length === 1
    ? `\n\nReason: ${cleanReasons[0]}`
    : `\n\nReasons:\n${cleanReasons.map(reason => `- ${reason}`).join('\n')}`;
}

function normalizeAssetAuditDateTime(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  return raw.replace('T', ' ').replace(/\.\d+$/, '');
}

function formatAssetAuditDateTime(value) {
  const normalized = normalizeAssetAuditDateTime(value);
  const match = normalized.match(/^(\d{4})-(\d{2})-(\d{2})(?:\s+(\d{2}):(\d{2})(?::\d{2})?)?$/);
  if (!match) return normalized || '-';
  return `${match[1]}/${match[2]}/${match[3]}`;
}

function assetAuditValueText(value) {
  if (value === true) return 'Yes';
  if (value === false) return 'No';
  const text = String(value ?? '').trim();
  return text || 'Blank';
}

function assetChangeHistoryHtml(asset) {
  const history = Array.isArray(asset?.changeHistory) ? asset.changeHistory : [];
  if (!history.length) {
    return '<div style="color:#666;font-size:13px;">No manual edit history yet.</div>';
  }

  return history
    .slice()
    .reverse()
    .map(record => {
      const changes = Array.isArray(record.changes) ? record.changes : [];
      const changeRows = changes.length
        ? changes.map(change => `
            <li style="margin:4px 0;">
              <strong>${escapeHtml(change.label || change.field || 'Field')}</strong>:
              ${escapeHtml(assetAuditValueText(change.old))}
              &rarr;
              ${escapeHtml(assetAuditValueText(change.new))}
            </li>
          `).join('')
        : '<li style="margin:4px 0;">Updated asset record</li>';

      return `
        <div style="border-top:1px solid #e9ecef;padding:10px 0;">
          <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:13px;color:#495057;">
            <strong>${escapeHtml(record.action === 'created' ? 'Created' : 'Updated')}</strong>
            <span>${escapeHtml(formatAssetAuditDateTime(record.date))}${record.user ? ` by ${escapeHtml(record.user)}` : ''}</span>
          </div>
          <ul style="margin:6px 0 0 18px;padding:0;font-size:13px;color:#495057;">
            ${changeRows}
          </ul>
        </div>
      `;
    })
    .join('');
}

function isAssetDisposed(asset) {
  return !!(asset && (asset.isDisposed || asset.isDecommissioned || asset.status === 'disposed' || asset.status === 'decommissioned'));
}

function assetStatusClass(status) {
  return `status-${String(status || 'available').trim().toLowerCase().replace(/[^a-z0-9_-]+/g, '-')}`;
}

function statusBadgeHtml(status, label = null) {
  const cleanStatus = String(status || 'available').trim().toLowerCase() || 'available';
  const text = label || cleanStatus.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  return `<span class="asset-badge ${assetStatusClass(cleanStatus)}">${escapeHtml(text)}</span>`;
}

function safePdfHexColour(value, fallback) {
  const colour = String(value || '').trim();
  return /^#[0-9A-Fa-f]{6}$/.test(colour) ? colour : fallback;
}

function pdfInlineBadgeHtml(label, background, color, options = {}) {
  const bg = safePdfHexColour(background, '#e5e7eb');
  const fg = safePdfHexColour(color, getReadableTextColour(bg));
  const extraStyle = options.style ? String(options.style) : '';
  const title = options.title ? ` title="${escapeHtmlAttr(options.title)}"` : '';
  return `<span${title} style="display:inline-block;padding:2px 6px;border-radius:999px;font-size:.95em;font-weight:700;line-height:1.2;white-space:nowrap;background:${bg};color:${fg};-webkit-print-color-adjust:exact;print-color-adjust:exact;${extraStyle}">${escapeHtml(label)}</span>`;
}

function getAssetConditionStatus(asset) {
  if (!asset) return 'available';
  if (asset.isDisposed || asset.isDecommissioned || asset.status === 'disposed' || asset.status === 'decommissioned') return 'decommissioned';
  if (asset.isMissing || asset.status === 'missing') return 'missing';
  if (asset.isOOC || asset.status === 'ooc') return 'ooc';
  if (asset.isUntagged || asset.status === 'untagged') return 'untagged';
  if (asset.isDegraded || asset.status === 'degraded') return 'degraded';
  return 'available';
}

// Shared by selectors that are initialized both inside and outside the
// DOMContentLoaded handler.
function getAssetStatusBadge(asset) {
  if (!asset) return statusBadgeHtml('available', 'Available');

  const condition = getAssetConditionStatus(asset);
  if (condition !== 'available') {
    const label = condition === 'ooc'
      ? 'OOC'
      : condition.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
    return statusBadgeHtml(condition, label);
  }
  if (asset.status === 'deployed') return statusBadgeHtml('deployed', 'Deployed');

  return statusBadgeHtml('available', 'Available');
}

function assetFlagBadgesHtml(asset) {
  if (asset?.isBulk) {
    const badges = [];
    const oocQty = Math.max(0, Number(asset.bulkOOCQuantity || 0) || 0);
    const missingQty = Math.max(0, Number(asset.bulkMissingQuantity || 0) || 0);
    const degradedQty = Math.max(0, Number(asset.bulkDegradedQuantity || 0) || 0);
    let hasOOCBadge = false;
    let hasMissingBadge = false;
    let hasDegradedBadge = false;
    if (asset.isMissing || asset.status === 'missing') {
      badges.push(statusBadgeHtml('missing', missingQty ? `${missingQty} Missing` : 'Missing'));
      hasMissingBadge = true;
    }
    if (asset.isOOC || asset.status === 'ooc') {
      badges.push(statusBadgeHtml('ooc', oocQty ? `${oocQty} OOC` : 'OOC'));
      hasOOCBadge = true;
    }
    if (asset.isDegraded || asset.status === 'degraded') {
      badges.push(statusBadgeHtml('degraded', degradedQty ? `${degradedQty} Degraded` : 'Degraded'));
      hasDegradedBadge = true;
    }
    if (asset.isDisposed || asset.isDecommissioned || asset.status === 'disposed' || asset.status === 'decommissioned') badges.push(statusBadgeHtml('decommissioned', 'Decommissioned'));
    if (!hasOOCBadge && oocQty > 0) badges.push(statusBadgeHtml('ooc', `${oocQty} OOC`));
    if (!hasMissingBadge && missingQty > 0) badges.push(statusBadgeHtml('missing', `${missingQty} Missing`));
    if (!hasDegradedBadge && degradedQty > 0) badges.push(statusBadgeHtml('degraded', `${degradedQty} Degraded`));
    return badges.length ? badges.join(' ') : statusBadgeHtml('available', 'OK');
  }

  const status = getAssetConditionStatus(asset);
  const label = status === 'available'
    ? 'OK'
    : (status === 'ooc' ? 'OOC' : status.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase()));
  return statusBadgeHtml(status, label);
}

function maintenanceStatusMeta(value) {
  const cleanValue = String(value || 'nochange').trim().toLowerCase();
  const map = {
    nochange: { label: 'No Change', color: '#495057' },
    ok: { label: 'OK / Clear Status', color: '#28a745' },
    ooc: { label: 'OOC', color: '#dc3545' },
    missing: { label: 'Missing', color: '#fd7e14' },
    untagged: { label: 'Untagged', color: '#0e7490' },
    degraded: { label: 'Degraded', color: '#856404' },
    decommissioned: { label: 'Decommissioned', color: '#6c757d' },
    disposed: { label: 'Decommissioned', color: '#6c757d' }
  };
  return map[cleanValue] || map.nochange;
}

function applyMaintenanceStatusSelectStyle(selectEl) {
  if (!selectEl) return;

  const meta = maintenanceStatusMeta(selectEl.value);
  selectEl.style.color = meta.color;
  selectEl.style.fontWeight = selectEl.value === 'nochange' ? '400' : '600';
  selectEl.style.borderColor = meta.color;

  Array.from(selectEl.options || []).forEach(option => {
    const optionMeta = maintenanceStatusMeta(option.value);
    option.style.color = optionMeta.color;
    option.style.fontWeight = option.value === 'nochange' ? '400' : '600';
  });
  refreshMaintenanceCustomSelect(selectEl);
}

function initialiseMaintenanceStatusSelects(root = document) {
  root.querySelectorAll('[data-maintenance-status-select="true"]').forEach(selectEl => {
    applyMaintenanceStatusSelectStyle(selectEl);
    enhanceMaintenanceCustomSelect(selectEl, 'status');
    if (selectEl.dataset.statusColourBound === 'true') return;
    selectEl.addEventListener('change', () => applyMaintenanceStatusSelectStyle(selectEl));
    selectEl.dataset.statusColourBound = 'true';
  });
}

function ensureMaintenanceCustomSelectStyles() {
  if (document.getElementById('maintenance-custom-select-styles')) return;
  const style = document.createElement('style');
  style.id = 'maintenance-custom-select-styles';
  style.textContent = `
    .maintenance-native-select {
      position: absolute !important;
      width: 1px !important;
      height: 1px !important;
      padding: 0 !important;
      margin: 0 !important;
      opacity: 0 !important;
      pointer-events: none !important;
    }
    .maintenance-custom-select { position: relative; width: 100%; }
    .maintenance-custom-select-trigger {
      width: 100%; min-height: 42px; padding: 8px 34px 8px 11px;
      border: 1px solid #cbd5d1; border-radius: 6px; background: #fff;
      display: flex; align-items: center; gap: 8px; text-align: left;
      font: inherit; font-size: 13px; font-weight: 700; cursor: pointer;
      position: relative; transition: border-color .15s, box-shadow .15s, background .15s;
    }
    .maintenance-custom-select-trigger:hover { background: #f8fbfa; }
    .maintenance-custom-select-trigger:focus-visible { outline: 0; box-shadow: 0 0 0 3px rgba(15,118,110,.14); }
    .maintenance-custom-select-trigger::after {
      content: ''; position: absolute; right: 12px; top: 50%; width: 7px; height: 7px;
      border-right: 2px solid currentColor; border-bottom: 2px solid currentColor;
      transform: translateY(-65%) rotate(45deg); transition: transform .15s;
    }
    .maintenance-custom-select.open .maintenance-custom-select-trigger::after { transform: translateY(-30%) rotate(225deg); }
    .maintenance-custom-select-swatch { width: 9px; height: 9px; border-radius: 50%; background: var(--option-color); flex: none; }
    .maintenance-custom-select-menu {
      display: none; position: absolute; left: 0; right: 0; top: calc(100% + 4px); z-index: 80;
      padding: 5px; border: 1px solid #cbdad5; border-radius: 6px; background: #fff;
      box-shadow: 0 12px 28px rgba(15,23,42,.16); max-height: 250px; overflow: auto;
    }
    .maintenance-custom-select.open .maintenance-custom-select-menu { display: grid; gap: 3px; animation: maintenanceSelectReveal .13s ease-out; }
    .maintenance-custom-select-option {
      width: 100%; min-height: 35px; padding: 7px 9px; border: 1px solid transparent;
      border-radius: 5px; background: transparent; display: flex; align-items: center; gap: 8px;
      color: var(--option-color); text-align: left; font: inherit; font-size: 12px; font-weight: 700; cursor: pointer;
    }
    .maintenance-custom-select-option:hover,.maintenance-custom-select-option.selected { background: var(--option-background); border-color: color-mix(in srgb,var(--option-color) 24%,transparent); }
    @keyframes maintenanceSelectReveal { from { opacity:0;transform:translateY(-3px) } to { opacity:1;transform:none } }
  `;
  document.head.appendChild(style);
}

function maintenanceCustomSelectMeta(kind, value) {
  if (kind === 'type') {
    const meta = maintenanceLogTypeMeta(value);
    const colours = {
      'General': '#64748b',
      'Preventative maintenance': '#1594ad',
      'Fault': '#dc5965',
      'Update': '#8b6fd6',
      'Repair': '#d89422',
      'Asset check': '#2ca46f'
    };
    return { label: meta.normalized, color: colours[meta.normalized] || colours.General, background: meta.background };
  }
  const meta = maintenanceStatusMeta(value);
  const backgrounds = {
    nochange: '#f1f3f5', ok: '#e7f6ee', ooc: '#fdebed', missing: '#fff0e2', untagged: '#e7f7fa',
    degraded: '#fff3df', decommissioned: '#edf0f2', disposed: '#edf0f2'
  };
  return { ...meta, background: backgrounds[String(value || '').toLowerCase()] || '#f1f3f5' };
}

function closeMaintenanceCustomSelects(except = null) {
  document.querySelectorAll('.maintenance-custom-select.open').forEach(wrapper => {
    if (wrapper === except) return;
    wrapper.classList.remove('open');
    wrapper.querySelector('.maintenance-custom-select-trigger')?.setAttribute('aria-expanded', 'false');
  });
}

function refreshMaintenanceCustomSelect(selectEl) {
  if (!selectEl?.dataset.maintenanceCustomKind) return;
  const wrapper = selectEl.nextElementSibling;
  if (!wrapper?.classList.contains('maintenance-custom-select')) return;
  const kind = selectEl.dataset.maintenanceCustomKind;
  const meta = maintenanceCustomSelectMeta(kind, selectEl.value);
  const trigger = wrapper.querySelector('.maintenance-custom-select-trigger');
  if (trigger) {
    trigger.style.color = meta.color;
    trigger.style.borderColor = meta.color;
    trigger.disabled = selectEl.disabled;
    trigger.querySelector('.maintenance-custom-select-swatch')?.style.setProperty('--option-color', meta.color);
    const label = trigger.querySelector('.maintenance-custom-select-label');
    if (label) label.textContent = meta.label;
  }
  wrapper.querySelectorAll('.maintenance-custom-select-option').forEach(option => {
    const selected = option.dataset.value === selectEl.value;
    option.classList.toggle('selected', selected);
    option.setAttribute('aria-selected', String(selected));
  });
}

function enhanceMaintenanceCustomSelect(selectEl, kind) {
  if (!selectEl || selectEl.dataset.maintenanceCustomKind) return;
  ensureMaintenanceCustomSelectStyles();
  selectEl.dataset.maintenanceCustomKind = kind;
  selectEl.classList.add('maintenance-native-select');
  selectEl.tabIndex = -1;
  selectEl.setAttribute('aria-hidden', 'true');

  const selectedMeta = maintenanceCustomSelectMeta(kind, selectEl.value);
  const wrapper = document.createElement('div');
  wrapper.className = 'maintenance-custom-select';
  wrapper.innerHTML = `
    <button type="button" class="maintenance-custom-select-trigger" aria-haspopup="listbox" aria-expanded="false" style="color:${selectedMeta.color};border-color:${selectedMeta.color}">
      <span class="maintenance-custom-select-swatch" style="--option-color:${selectedMeta.color}"></span>
      <span class="maintenance-custom-select-label">${escapeHtml(selectedMeta.label)}</span>
    </button>
    <div class="maintenance-custom-select-menu" role="listbox">
      ${Array.from(selectEl.options).map(option => {
        const meta = maintenanceCustomSelectMeta(kind, option.value);
        return `<button type="button" class="maintenance-custom-select-option${option.value === selectEl.value ? ' selected' : ''}" role="option" aria-selected="${option.value === selectEl.value}" data-value="${escapeHtmlAttr(option.value)}" style="--option-color:${meta.color};--option-background:${meta.background}"><span class="maintenance-custom-select-swatch" style="--option-color:${meta.color}"></span><span>${escapeHtml(meta.label)}</span></button>`;
      }).join('')}
    </div>
  `;
  selectEl.insertAdjacentElement('afterend', wrapper);
  const trigger = wrapper.querySelector('.maintenance-custom-select-trigger');
  trigger?.addEventListener('click', () => {
    const opening = !wrapper.classList.contains('open');
    closeMaintenanceCustomSelects(wrapper);
    wrapper.classList.toggle('open', opening);
    trigger.setAttribute('aria-expanded', String(opening));
  });
  wrapper.querySelectorAll('.maintenance-custom-select-option').forEach(option => {
    option.addEventListener('click', () => {
      selectEl.value = option.dataset.value || '';
      selectEl.dispatchEvent(new Event('change', { bubbles: true }));
      closeMaintenanceCustomSelects();
      trigger?.focus();
    });
  });
  const label = document.querySelector(`label[for="${selectEl.id}"]`);
  label?.addEventListener('click', event => { event.preventDefault(); trigger?.focus(); });
  if (document.body.dataset.maintenanceSelectDismissBound !== 'true') {
    document.addEventListener('click', event => {
      if (!event.target.closest('.maintenance-custom-select')) closeMaintenanceCustomSelects();
    });
    document.addEventListener('keydown', event => { if (event.key === 'Escape') closeMaintenanceCustomSelects(); });
    document.body.dataset.maintenanceSelectDismissBound = 'true';
  }
  refreshMaintenanceCustomSelect(selectEl);
}

function maintenanceStatusSelectHtml(id, name, selected = 'nochange') {
  const value = String(selected || 'nochange');
  const option = (optionValue) => {
    const meta = maintenanceStatusMeta(optionValue);
    return `<option value="${optionValue}" style="color:${meta.color};font-weight:${optionValue === 'nochange' ? '400' : '600'};" ${value === optionValue ? 'selected' : ''}>${meta.label}</option>`;
  };
  return `
    <select id="${id}" name="${name}" class="form-input" data-maintenance-status-select="true" onchange="applyMaintenanceStatusSelectStyle(this)">
      ${option('nochange')}
      ${option('ok')}
      ${option('ooc')}
      ${option('missing')}
      ${option('untagged')}
      ${option('degraded')}
      ${option('decommissioned')}
    </select>
  `;
}


async function confirmDegradedAssetUse(assetId, assetDetails = null) {
  const identifier = getAssetIdentifierForApi(assetDetails) || assetId;
  const fullAsset = getAssetByApiIdentifier(identifier);
  const asset = assetDetails
    ? {
        ...assetDetails,
        maintenanceLogRecords: (
          Array.isArray(assetDetails.maintenanceLogRecords) && assetDetails.maintenanceLogRecords.length
            ? assetDetails.maintenanceLogRecords
            : fullAsset?.maintenanceLogRecords
        ),
        maintenanceLogs: (
          Array.isArray(assetDetails.maintenanceLogs) && assetDetails.maintenanceLogs.length
            ? assetDetails.maintenanceLogs
            : fullAsset?.maintenanceLogs
        ),
        degradedReasons: (
          Array.isArray(assetDetails.degradedReasons) && assetDetails.degradedReasons.length
            ? assetDetails.degradedReasons
            : fullAsset?.degradedReasons
        ),
      }
    : fullAsset;

  if (!isAssetDegraded(asset)) return true;
  playWorkflowTone('error');

  const label = [asset?.brand, asset?.model, asset?.description].filter(Boolean).join(' ');
  const reasons = getAssetDegradedReasons(asset);
  return showAppConfirm({
    title: 'Degraded Asset',
    message: `${identifier}${label ? ` (${label})` : ''} is marked as Degraded.${degradedReasonMessage(reasons)}\n\nIt can still be used for show, but it may not be fully functional. Continue preparing this asset?`,
    confirmText: 'Continue',
    cancelText: 'Cancel',
    variant: 'warning',
  });
}

function showApiWarning(response) {
  if (response && response.warning) {
    return showAppAlert({
      title: 'Warning',
      message: response.warning,
      variant: 'warning',
    });
  }
  return Promise.resolve();
}


function getAssignedAssetDisplay(asset) {
  if (!asset) return '';
  if (asset.isBulk) return `${asset.name || 'Bulk Item'} (Qty: ${asset.quantity || 1})`;
  return asset.id || '';
}


// Delivery Order edit state
const deliveryOrderWorkspaceCache = new Map();
const deliveryOrderBaseCache = new Map();
const deliveryOrderSaveTimers = new Map();
const deliveryOrderActiveSaves = new Map();
const deliveryOrderSaveVersions = new Map();

function cloneDoWorkspace(value) {
  if (value === undefined) return {};
  if (value === null) return null;
  return JSON.parse(JSON.stringify(value));
}

function doWorkspaceValuesEqual(left, right) {
  return JSON.stringify(left) === JSON.stringify(right);
}

function doWorkspaceContentEqual(left, right) {
  const leftContent = cloneDoWorkspace(left || {});
  const rightContent = cloneDoWorkspace(right || {});
  delete leftContent.updatedAt;
  delete rightContent.updatedAt;
  return doWorkspaceValuesEqual(leftContent, rightContent);
}

function mergeDoValue(baseValue, localValue, latestValue) {
  if (
    baseValue && localValue && latestValue
    && typeof baseValue === 'object'
    && typeof localValue === 'object'
    && typeof latestValue === 'object'
    && !Array.isArray(baseValue)
    && !Array.isArray(localValue)
    && !Array.isArray(latestValue)
  ) {
    return mergeDoKeyedObject(baseValue, localValue, latestValue);
  }
  return cloneDoWorkspace(localValue);
}

function mergeDoKeyedObject(baseValue, localValue, latestValue) {
  const base = baseValue && typeof baseValue === 'object' ? baseValue : {};
  const local = localValue && typeof localValue === 'object' ? localValue : {};
  const merged = cloneDoWorkspace(
    latestValue && typeof latestValue === 'object' ? latestValue : {}
  );
  new Set([...Object.keys(base), ...Object.keys(local)]).forEach(key => {
    if (!Object.prototype.hasOwnProperty.call(local, key)) {
      if (Object.prototype.hasOwnProperty.call(base, key)) delete merged[key];
      return;
    }
    if (!doWorkspaceValuesEqual(local[key], base[key])) {
      merged[key] = mergeDoValue(base[key], local[key], merged[key]);
    }
  });
  return merged;
}

function mergeDoRows(baseRows, localRows, latestRows) {
  const base = Array.isArray(baseRows) ? baseRows : [];
  const local = Array.isArray(localRows) ? localRows : [];
  const latest = Array.isArray(latestRows) ? latestRows : [];
  const baseById = new Map(base.map(row => [String(row?.id || ''), row]));
  const localById = new Map(local.map(row => [String(row?.id || ''), row]));
  const latestById = new Map(latest.map(row => [String(row?.id || ''), row]));
  const merged = local.map(row => {
    const id = String(row?.id || '');
    const baseRow = baseById.get(id);
    const latestRow = latestById.get(id);
    if (baseRow && doWorkspaceValuesEqual(row, baseRow)) {
      return latestRow ? cloneDoWorkspace(latestRow) : null;
    }
    return baseRow && latestRow
      ? mergeDoKeyedObject(baseRow, row, latestRow)
      : cloneDoWorkspace(row);
  }).filter(Boolean);
  const included = new Set(merged.map(row => String(row?.id || '')));
  latest.forEach(row => {
    const id = String(row?.id || '');
    if (!included.has(id) && !baseById.has(id)) merged.push(cloneDoWorkspace(row));
  });
  return merged;
}

function mergeDoCustomBuckets(baseValue, localValue, latestValue) {
  const base = baseValue || {};
  const local = localValue || {};
  const latest = latestValue || {};
  const merged = {};
  new Set([...Object.keys(base), ...Object.keys(local), ...Object.keys(latest)])
    .forEach(department => {
      merged[department] = mergeDoRows(
        base[department], local[department], latest[department]
      );
    });
  return merged;
}

function mergeDoWorkspaceConflict(baseValue, localValue, latestValue) {
  const base = ensureDoEditBuckets(cloneDoWorkspace(baseValue));
  const local = ensureDoEditBuckets(cloneDoWorkspace(localValue));
  const latest = ensureDoEditBuckets(cloneDoWorkspace(latestValue));
  const merged = cloneDoWorkspace(latest);
  merged.overrides = mergeDoKeyedObject(base.overrides, local.overrides, latest.overrides);
  merged.deleted = mergeDoKeyedObject(base.deleted, local.deleted, latest.deleted);
  merged.ordering = mergeDoKeyedObject(base.ordering, local.ordering, latest.ordering);
  merged.document = mergeDoKeyedObject(base.document, local.document, latest.document);
  merged.custom = mergeDoCustomBuckets(base.custom, local.custom, latest.custom);
  if (!doWorkspaceValuesEqual(local.subprojectOrder, base.subprojectOrder)) {
    merged.subprojectOrder = cloneDoWorkspace(local.subprojectOrder);
  }
  merged.documentVersion = latest.documentVersion;
  merged.updatedAt = local.updatedAt || latest.updatedAt;
  return ensureDoEditBuckets(merged);
}

function getDoEdits(eventId, deptNames = []) {
  const blank = ensureDoEditBuckets({ overrides: {}, custom: {}, ordering: {} }, deptNames);
  if (deliveryOrderWorkspaceCache.has(String(eventId))) {
    return ensureDoEditBuckets(deliveryOrderWorkspaceCache.get(String(eventId)), deptNames);
  }
  try {
    const raw = localStorage.getItem(`doEdits/${eventId}`);
    if (!raw) return blank;
    const data = JSON.parse(raw);
    return ensureDoEditBuckets(data, deptNames);
  } catch { return blank; }
}
function saveDoEdits(eventId, data, options = {}) {
  const key = String(eventId);
  const workspace = ensureDoEditBuckets(data);
  workspace.updatedAt = new Date().toISOString();
  deliveryOrderWorkspaceCache.set(key, workspace);
  deliveryOrderSaveVersions.set(key, (deliveryOrderSaveVersions.get(key) || 0) + 1);
  localStorage.setItem(`doEdits/${eventId}`, JSON.stringify(workspace));
  clearTimeout(deliveryOrderSaveTimers.get(key));
  deliveryOrderSaveTimers.delete(key);
  if (options.immediate === true) {
    const request = persistDoEdits(eventId);
    request.catch(() => {});
    return request;
  }
  deliveryOrderSaveTimers.set(key, setTimeout(() => {
    persistDoEdits(eventId).catch(() => {});
  }, 450));
  return Promise.resolve(workspace);
}
function clearDoEdits(eventId) {
  const key = String(eventId);
  clearTimeout(deliveryOrderSaveTimers.get(key));
  deliveryOrderSaveTimers.delete(key);
  const base = deliveryOrderBaseCache.get(key) || getDoEdits(eventId);
  const blank = ensureDoEditBuckets({ documentVersion: base.documentVersion });
  deliveryOrderWorkspaceCache.set(key, blank);
  deliveryOrderSaveVersions.set(key, (deliveryOrderSaveVersions.get(key) || 0) + 1);
  localStorage.setItem(`doEdits/${eventId}`, JSON.stringify(blank));
  const previousSave = deliveryOrderActiveSaves.get(key);
  const request = Promise.resolve(previousSave)
    .catch(() => {})
    .then(async () => {
      let expectedVersion = Math.max(0, Number(base.documentVersion) || 0);
      try {
        return await apiCall(
          `/api/events/${encodeURIComponent(eventId)}/delivery-order?expectedVersion=${expectedVersion}`,
          'DELETE'
        );
      } catch (error) {
        if (error.payload?.code !== 'document_version_conflict') throw error;
        expectedVersion = Math.max(0, Number(error.payload.actualVersion) || 0);
        return apiCall(
          `/api/events/${encodeURIComponent(eventId)}/delivery-order?expectedVersion=${expectedVersion}`,
          'DELETE'
        );
      }
    })
    .then(response => {
      const saved = ensureDoEditBuckets(response.data || blank);
      deliveryOrderBaseCache.set(key, cloneDoWorkspace(saved));
      deliveryOrderWorkspaceCache.set(key, saved);
      localStorage.setItem(`doEdits/${eventId}`, JSON.stringify(saved));
      return response;
    })
    .catch(error => showNotification('error', error.message || 'Failed to reset Delivery Order'));
  deliveryOrderActiveSaves.set(key, request);
  request.finally(() => {
    if (deliveryOrderActiveSaves.get(key) === request) deliveryOrderActiveSaves.delete(key);
  });
}

async function loadDoEdits(eventId) {
  const key = String(eventId);
  if (deliveryOrderWorkspaceCache.has(key)) return getDoEdits(eventId);
  let localWorkspace = null;
  try {
    const raw = localStorage.getItem(`doEdits/${eventId}`);
    if (raw) localWorkspace = ensureDoEditBuckets(JSON.parse(raw));
  } catch {}
  try {
    const response = await apiCall(`/api/events/${encodeURIComponent(eventId)}/delivery-order`);
    const serverWorkspace = ensureDoEditBuckets(response.data || {});
    const hasServerData = Object.keys(response.data || {}).length > 0;
    // A local workspace at the same server version contains edits that were
    // made after that version loaded but did not finish uploading (for example,
    // because the app restarted). Recover those edits, while discarding an old
    // browser cache whenever the server has advanced to a newer version.
    const serverVersion = Math.max(0, Number(serverWorkspace.documentVersion) || 0);
    const localVersion = Math.max(0, Number(localWorkspace?.documentVersion) || 0);
    const localHasPendingChanges = !!localWorkspace && (
      !hasServerData
      || (
        localVersion === serverVersion
        && !doWorkspaceContentEqual(localWorkspace, serverWorkspace)
      )
    );
    const workspace = localHasPendingChanges
      ? mergeDoWorkspaceConflict(serverWorkspace, localWorkspace, serverWorkspace)
      : serverWorkspace;
    deliveryOrderBaseCache.set(key, cloneDoWorkspace(serverWorkspace));
    deliveryOrderWorkspaceCache.set(key, workspace);
    localStorage.setItem(`doEdits/${eventId}`, JSON.stringify(workspace));
    if (localHasPendingChanges) {
      deliveryOrderSaveVersions.set(key, (deliveryOrderSaveVersions.get(key) || 0) + 1);
      deliveryOrderSaveTimers.set(key, setTimeout(() => {
        persistDoEdits(eventId).catch(() => {});
      }, 0));
    }
    return workspace;
  } catch (error) {
    const fallback = localWorkspace || ensureDoEditBuckets({});
    deliveryOrderWorkspaceCache.set(key, fallback);
    return fallback;
  }
}

async function persistDoEdits(eventId) {
  const key = String(eventId);
  clearTimeout(deliveryOrderSaveTimers.get(key));
  deliveryOrderSaveTimers.delete(key);
  const previousSave = deliveryOrderActiveSaves.get(key);
  if (previousSave) await previousSave.catch(() => {});
  const saveVersion = deliveryOrderSaveVersions.get(key) || 0;
  const base = ensureDoEditBuckets(cloneDoWorkspace(
    deliveryOrderBaseCache.get(key) || { documentVersion: getDoEdits(eventId).documentVersion }
  ));
  let workspace = ensureDoEditBuckets(cloneDoWorkspace(getDoEdits(eventId)));
  let request = null;
  try {
    let response;
    for (let attempt = 0; attempt < 2; attempt += 1) {
      request = apiCall(
        `/api/events/${encodeURIComponent(eventId)}/delivery-order`,
        'PUT',
        { ...workspace, expectedVersion: base.documentVersion }
      );
      deliveryOrderActiveSaves.set(key, request);
      try {
        response = await request;
        break;
      } catch (error) {
        if (
          attempt > 0
          || error.payload?.code !== 'document_version_conflict'
          || !error.payload?.data
        ) throw error;
        const latest = ensureDoEditBuckets(error.payload.data);
        workspace = mergeDoWorkspaceConflict(base, workspace, latest);
        base.documentVersion = latest.documentVersion;
        Object.assign(base, cloneDoWorkspace(latest));
        deliveryOrderBaseCache.set(key, cloneDoWorkspace(latest));
        deliveryOrderWorkspaceCache.set(key, workspace);
        localStorage.setItem(`doEdits/${eventId}`, JSON.stringify(workspace));
        showNotification(
          'warning',
          'Another user updated this Delivery Order. Their changes were merged with yours.'
        );
      }
    }
    const saved = ensureDoEditBuckets(response?.data || workspace);
    deliveryOrderBaseCache.set(key, cloneDoWorkspace(saved));
    if ((deliveryOrderSaveVersions.get(key) || 0) === saveVersion) {
      deliveryOrderWorkspaceCache.set(key, saved);
      localStorage.setItem(`doEdits/${eventId}`, JSON.stringify(saved));
    } else {
      const newerLocal = getDoEdits(eventId);
      const rebased = mergeDoWorkspaceConflict(workspace, newerLocal, saved);
      deliveryOrderWorkspaceCache.set(key, rebased);
      localStorage.setItem(`doEdits/${eventId}`, JSON.stringify(rebased));
      clearTimeout(deliveryOrderSaveTimers.get(key));
      deliveryOrderSaveTimers.set(key, setTimeout(() => {
        persistDoEdits(eventId).catch(() => {});
      }, 100));
    }
    return saved;
  } catch (error) {
    showNotification('error', error.message || 'Failed to save Delivery Order');
    clearTimeout(deliveryOrderSaveTimers.get(key));
    deliveryOrderSaveTimers.set(key, setTimeout(() => {
      persistDoEdits(eventId).catch(() => {});
    }, 2000));
    throw error;
  } finally {
    if (deliveryOrderActiveSaves.get(key) === request) deliveryOrderActiveSaves.delete(key);
  }
}

async function flushDoEdits(eventId) {
  const key = String(eventId);
  if (deliveryOrderSaveTimers.has(key)) await persistDoEdits(eventId);
  if (deliveryOrderActiveSaves.has(key)) {
    await deliveryOrderActiveSaves.get(key).catch(() => {});
  }
}
/* stable key for model-group rows */
function makeModelKey(mg) {
  return `MG|${mg.department||''}|${mg.brand||''}|${mg.model||''}|${mg.description||''}`;
}

function makeQtyInputId(department, brand, model, description = '') {
  const raw = `${department || ''}|${brand || ''}|${model || ''}|${description || ''}`;

  return `qty-${encodeURIComponent(raw)
    .replace(/%/g, '_')
    .replace(/[^A-Za-z0-9_-]/g, '_')}`;
}

let isClickHandlerSetup = false;
let processingAssets = new Set();

// Date formatting for server-provided event dates.
function formatDate(dateStr) {
  if (!dateStr) return '';

  // Handle YYYY/MM/DD format from backend
  if (dateStr.includes('/')) {
    const dateParts = dateStr.split('/');
    if (dateParts.length === 3) {
      const [year, month, day] = dateParts;
      const isoDate = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
      return new Date(isoDate).toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
      });
    }
  }

  // Fallback for other date formats
  return new Date(dateStr).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

// Function to convert YYYY/MM/DD to YYYY-MM-DD for HTML date inputs
function formatDateForInput(dateStr) {
  if (!dateStr) return '';

  // Handle YYYY/MM/DD format from backend
  if (dateStr.includes('/')) {
    const dateParts = dateStr.split('/');
    if (dateParts.length === 3) {
      const [year, month, day] = dateParts;
      return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
    }
  }

  // Fallback: try parsing as regular date
  const date = new Date(dateStr);
  if (!isNaN(date.getTime())) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  return '';
}

function setupSingleAssetClickHandler() {
    // Prevent multiple setups
    if (isClickHandlerSetup) {
        return;
    }

    // Remove ALL possible existing listeners
    const oldHandler1 = document._assetClickHandler;
    const oldHandler2 = document._customAssetHandler;
    const oldHandler3 = window.handleAssetActionClick;
    const oldHandler4 = window.handleCustomAssetClick;

    if (oldHandler1) document.removeEventListener('click', oldHandler1);
    if (oldHandler2) document.removeEventListener('click', oldHandler2);
    if (oldHandler3) document.removeEventListener('click', oldHandler3);
    if (oldHandler4) document.removeEventListener('click', oldHandler4);

    // Create the ONE and ONLY click handler for ALL button types
    const singleClickHandler = async function(event) {
        // Handle prepare/unprepare buttons
        if (event.target.classList.contains('asset-action-btn') ||
            event.target.classList.contains('custom-asset-btn')) {

            event.preventDefault();
            event.stopPropagation();

            const eventId = event.target.dataset.eventId;
            const assetId = decodeURIComponent(event.target.dataset.assetId);
            const action = event.target.dataset.action;

            // Create unique key for this asset
            const assetKey = `${eventId}-${assetId}`;

            // Check if already processing
            if (processingAssets.has(assetKey)) {
                return false;
            }

            processingAssets.add(assetKey);

            if (action === 'prepare') {
                prepareSpecificAsset(eventId, assetId).finally(() => {
                    processingAssets.delete(assetKey);
                });
            } else if (action === 'unprepare') {
                unprepareSpecificAsset(eventId, assetId).finally(() => {
                    processingAssets.delete(assetKey);
                });
            } else if (action === 'editCustom') {
                editCustomAsset(eventId, assetId);
                processingAssets.delete(assetKey);
            } else if (action === 'removeCustom') {
                removeCustomAsset(eventId, assetId).finally(() => {
                    processingAssets.delete(assetKey);
                });
            }

            return false;
        }

        // Handle removal buttons (remove from event)
        if (event.target.classList.contains('asset-remove-btn') ||
            event.target.classList.contains('custom-remove-btn')) {

            event.preventDefault();
            event.stopPropagation();

            const eventId = event.target.dataset.eventId;
            const assetId = decodeURIComponent(event.target.dataset.assetId);

            // Create unique key for this asset
            const assetKey = `${eventId}-${assetId}`;

            // Check if already processing
            if (processingAssets.has(assetKey)) {
                return false;
            }

            if (await showAppConfirm({
                title: 'Remove Asset',
                message: `Remove ${assetId} from this event?`,
                confirmText: 'Remove',
                cancelText: 'Cancel',
                variant: 'danger',
            })) {
                // Mark as processing
                processingAssets.add(assetKey);

                // Disable the button
                event.target.disabled = true;
                event.target.style.opacity = '0.5';

                // Process removal
                const cleanup = () => {
                    processingAssets.delete(assetKey);
                };

                removeAssetFromEvent(eventId, assetId).finally(cleanup);
            }

            return false;
        }

    };

    // Store reference and add listener
    document._singleAssetHandler = singleClickHandler;
    document.addEventListener('click', singleClickHandler, true); // Use capture phase

    isClickHandlerSetup = true;
}

// Global variables for maintenance functionality
let selectedMaintenanceAssets = new Set();
let maintenanceIdentifierLookupInProgress = false;

function removeExistingListeners() {
    // Remove any existing click handlers
    const existingHandler = document._assetClickHandler;
    if (existingHandler) {
        document.removeEventListener('click', existingHandler);
    }
}

function setupAssetClickHandler() {
    removeExistingListeners();

    const clickHandler = function(event) {
        if (event.target.classList.contains('asset-action-btn')) {
            event.preventDefault();
            event.stopPropagation();

            const eventId = event.target.dataset.eventId;
            const assetId = decodeURIComponent(event.target.dataset.assetId);
            const action = event.target.dataset.action;

            const assetKey = `${eventId}-${assetId}`;

            if (processingAssets.has(assetKey)) {
                return;
            }

            processingAssets.add(assetKey);

            const allButtonsForAsset = document.querySelectorAll(`[data-asset-id="${encodeURIComponent(assetId)}"]`);
            allButtonsForAsset.forEach(btn => {
                btn.disabled = true;
                btn.style.opacity = '0.6';
            });

            const cleanup = () => {
                processingAssets.delete(assetKey);
            };

            if (action === 'prepare') {
                prepareSpecificAsset(eventId, assetId)
                    .finally(cleanup);
            } else if (action === 'unprepare') {
                unprepareSpecificAsset(eventId, assetId)
                    .finally(cleanup);
            } else {
                cleanup();
            }

            return;
        }
    };

    document._assetClickHandler = clickHandler;

    document.addEventListener('click', clickHandler);
}

// Global utility function for JavaScript string escaping
function escapeJs(str) {
  if (!str) return '';
  return str.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/"/g, '\\"').replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t');
}

function escapeHtmlAttribute(str) {
  if (!str) return '';
  return str
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const BARCODE_SCANNER_SCRIPT_URLS = [
  '/static/js/vendor/html5-qrcode.min.js',
  'https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js'
];
const BARCODE_SCANNER_NATIVE_INTERVAL_MS = 80;
const BARCODE_SCANNER_NATIVE_MIN_FRAME_INTERVAL_MS = 45;
const BARCODE_SCANNER_NATIVE_VARIANT_INTERVAL_MS = 320;
let barcodeScannerScriptPromise = null;
let barcodeScannerState = {
  html5: null,
  stream: null,
  nativeTimer: null,
  nativeFrameHandle: null,
  nativeVideo: null,
  nativeDetector: null,
  nativeLastScanAt: 0,
  nativeLastVariantScanAt: 0,
  onScan: null,
  handling: false,
  statusTimer: null
};

const HTML5_QRCODE_FORMAT_NAMES = [
  'QR_CODE',
  'CODE_128',
  'CODE_39',
  'CODE_93',
  'CODABAR',
  'DATA_MATRIX',
  'EAN_13',
  'EAN_8',
  'ITF',
  'PDF_417',
  'UPC_A',
  'UPC_E'
];

const NATIVE_BARCODE_FORMATS = [
  'qr_code',
  'aztec',
  'code_128',
  'code_39',
  'code_93',
  'codabar',
  'data_matrix',
  'ean_13',
  'ean_8',
  'itf',
  'pdf417',
  'upc_a',
  'upc_e'
];

function normalizeScannedIdentifier(rawValue) {
  let value = String(rawValue || '')
    .replace(/[\u0000-\u001f]+/g, ' ')
    .trim();

  if (!value) return '';

  try {
    const url = new URL(value);
    const paramNames = ['assetId', 'asset_id', 'asset', 'id', 'serial', 'sn', 'container'];
    for (const name of paramNames) {
      const paramValue = url.searchParams.get(name);
      if (paramValue && paramValue.trim()) return paramValue.trim();
    }

    const lastPathPart = decodeURIComponent(url.pathname.split('/').filter(Boolean).pop() || '').trim();
    if (lastPathPart) return lastPathPart;
  } catch (e) {
    // Not a URL; keep processing as a raw code.
  }

  const prefixed = value.match(/^(?:asset(?:\s*id)?|serial(?:\s*(?:no|number))?|id|sn|container)\s*[:=#]\s*(.+)$/i);
  if (prefixed && prefixed[1]) {
    value = prefixed[1].trim();
  }

  return value;
}

function findAssetByIdentifier(identifier, assetList = assets) {
  const normalized = normalizeScannedIdentifier(identifier).toLowerCase();
  if (!normalized || !Array.isArray(assetList)) return null;

  return assetList.find(asset => {
    if (!asset) return false;
    const ids = [
      asset.id,
      asset.internalId,
      asset.bulkId,
      asset.displayId
    ].map(value => String(value || '').trim()).filter(Boolean);

    if (ids.some(value => value.toLowerCase() === normalized)) return true;

    const serials = [asset.serial, asset.serial2]
      .map(value => String(value || '').trim())
      .filter(Boolean);
    return serials.some(serial => serial.toLowerCase() === normalized);
  }) || null;
}

function getAssetIdFromIdentifier(identifier, assetList = assets) {
  const asset = findAssetByIdentifier(identifier, assetList);
  return asset ? getAssetIdentifierForApi(asset) : normalizeScannedIdentifier(identifier);
}

function scannerButtonHtml(onclick, label = 'Scan') {
  return `<button type="button" class="btn btn-primary scanner-action-btn" onclick="${onclick}" title="Use phone camera to scan QR or barcode">${label}</button>`;
}

