function bulkDeploymentDateText(deployment) {
  const startDate = deployment?.startDate ? formatDate(deployment.startDate) : '';
  const endDate = deployment?.endDate ? formatDate(deployment.endDate) : '';
  if (!startDate && !endDate) return '';
  if (!endDate || startDate === endDate) return startDate;
  return `${startDate} - ${endDate}`;
}

function setInventoryBulkDeploymentExpanded(encodedAssetId, expanded) {
  if (expanded) expandedInventoryBulkDeploymentIds.add(encodedAssetId);
  else expandedInventoryBulkDeploymentIds.delete(encodedAssetId);
}

function bulkDeploymentDetailsHtml(asset) {
  if (!asset?.isBulk || !Array.isArray(asset.bulkDeployments)) return '';

  const deployments = asset.bulkDeployments
    .map(deployment => ({
      ...deployment,
      quantity: Math.max(0, Number(deployment?.quantity || 0) || 0)
    }))
    .filter(deployment => deployment.quantity > 0);

  if (deployments.length === 0) return '';

  const deployedTotal = Math.max(
    0,
    Number(asset.deployedQuantity ?? deployments.reduce((sum, item) => sum + item.quantity, 0)) || 0
  );
  const encodedAssetId = encodeURIComponent(getAssetIdentifierForApi(asset));
  const openAttribute = expandedInventoryBulkDeploymentIds.has(encodedAssetId) ? ' open' : '';

  return `
    <details
      class="bulk-deployment-details"
      ontoggle="setInventoryBulkDeploymentExpanded('${escapeHtmlAttr(encodedAssetId)}', this.open)"
      ${openAttribute}
    >
      <summary>${escapeHtml(String(deployedTotal))} deployed</summary>
      <div class="bulk-deployment-menu" role="list">
        ${deployments.map((deployment) => {
          const eventId = deployment.eventId ? `#${deployment.eventId}` : '';
          const eventName = deployment.eventName || (deployment.eventId ? `Event ${deployment.eventId}` : 'Event');
          const dateText = bulkDeploymentDateText(deployment);
          return `
            <div class="bulk-deployment-row" role="listitem">
              <div class="bulk-deployment-main">
                <span class="bulk-deployment-event">${escapeHtml(eventName)}</span>
                ${eventId ? `<span class="bulk-deployment-event-id">${escapeHtml(eventId)}</span>` : ''}
              </div>
              <div class="bulk-deployment-meta">
                <span class="bulk-deployment-dates">${escapeHtml(dateText || 'Date not set')}</span>
                <span class="bulk-deployment-qty">${escapeHtml(String(deployment.quantity))} deployed</span>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    </details>
  `;
}

function inventoryAssetIdentifier(asset) {
  return getAssetIdentifierForApi(asset);
}

function normalizeAssetTags(value) {
  const source = Array.isArray(value) ? value : String(value || '').split(/[\s,]+/);
  const tags = [];
  const seen = new Set();
  source.forEach(item => {
    String(item || '').split(/[\s,]+/).forEach(part => {
      const tag = part.trim().replace(/^#+/, '').slice(0, 50);
      const key = tag.toLocaleLowerCase();
      if (!tag || seen.has(key) || tags.length >= 50) return;
      seen.add(key);
      tags.push(tag);
    });
  });
  return tags;
}

function assetTagSearchText(asset) {
  return normalizeAssetTags(asset?.tags).join(' ').toLocaleLowerCase();
}

function assetTagEditorTags(editorId) {
  const editor = document.getElementById(editorId);
  if (!editor) return [];
  try {
    return normalizeAssetTags(JSON.parse(editor.dataset.tags || '[]'));
  } catch (error) {
    return [];
  }
}

function assetTagEditorRender(editorId) {
  const editor = document.getElementById(editorId);
  const input = editor?.querySelector('.asset-tag-editor-input');
  if (!editor || !input) return;

  editor.querySelectorAll('.inventory-tag').forEach(tag => tag.remove());
  assetTagEditorTags(editorId).forEach(tag => {
    const chip = document.createElement('span');
    chip.className = 'inventory-tag';
    const label = document.createElement('span');
    label.textContent = tag;
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'inventory-tag-remove';
    remove.textContent = '\u00d7';
    remove.setAttribute('aria-label', `Remove tag ${tag}`);
    remove.addEventListener('click', () => assetTagEditorRemove(editorId, tag));
    chip.append(label, remove);
    editor.insertBefore(chip, input);
  });
}

function assetTagEditorSetTags(editorId, tags) {
  const editor = document.getElementById(editorId);
  if (!editor) return;
  editor.dataset.tags = JSON.stringify(normalizeAssetTags(tags));
  const input = editor.querySelector('.asset-tag-editor-input');
  if (input) input.value = '';
  assetTagEditorRender(editorId);
}

function assetTagEditorCommit(editorId) {
  const editor = document.getElementById(editorId);
  const input = editor?.querySelector('.asset-tag-editor-input');
  if (!input || !input.value.trim()) return;
  if (editorId === 'assetTagsEditor') editor.dataset.addAssetAutofilled = '';
  assetTagEditorSetTags(editorId, [...assetTagEditorTags(editorId), ...normalizeAssetTags(input.value)]);
}

function assetTagEditorRemove(editorId, tag) {
  const editor = document.getElementById(editorId);
  if (editorId === 'assetTagsEditor' && editor) editor.dataset.addAssetAutofilled = '';
  const target = String(tag || '').toLocaleLowerCase();
  assetTagEditorSetTags(
    editorId,
    assetTagEditorTags(editorId).filter(item => item.toLocaleLowerCase() !== target)
  );
}

function assetTagEditorKeydown(event, editorId) {
  if (event.key === 'Enter' || event.key === ',' || event.key === ' ') {
    event.preventDefault();
    assetTagEditorCommit(editorId);
    return;
  }
  if (event.key === 'Backspace' && !event.currentTarget.value) {
    const tags = assetTagEditorTags(editorId);
    if (tags.length) assetTagEditorRemove(editorId, tags[tags.length - 1]);
  }
}

function assetTagEditorInput(event, editorId) {
  if (/[\s,]/.test(event.currentTarget.value)) assetTagEditorCommit(editorId);
}

function assetTagEditorHtml(editorId, tags = []) {
  return `
    <div id="${escapeHtmlAttr(editorId)}" class="asset-tag-editor" data-tags="${escapeHtmlAttr(JSON.stringify(normalizeAssetTags(tags)))}">
      <input class="asset-tag-editor-input" type="text" placeholder="Type a tag and press Space" autocomplete="off"
             onkeydown="assetTagEditorKeydown(event, '${escapeHtmlAttr(editorId)}')"
             oninput="assetTagEditorInput(event, '${escapeHtmlAttr(editorId)}')"
             onblur="assetTagEditorCommit('${escapeHtmlAttr(editorId)}')">
    </div>
  `;
}

function inventoryAssetTagsHtml(asset, removable = false) {
  const tags = normalizeAssetTags(asset?.tags);
  if (!tags.length) return '';
  const assetId = inventoryAssetIdentifier(asset);
  return `<div class="inventory-tag-list">${tags.map(tag => `
    <span class="inventory-tag">
      <span>${escapeHtml(tag)}</span>
      ${removable ? `<button type="button" class="inventory-tag-remove" aria-label="Remove tag ${escapeHtmlAttr(tag)}" title="Remove tag" onclick="removeInventoryAssetTag('${escapeHtmlAttr(encodeURIComponent(assetId))}','${escapeHtmlAttr(encodeURIComponent(tag))}',event)">&times;</button>` : ''}
    </span>
  `).join('')}</div>`;
}

async function removeInventoryAssetTag(encodedAssetId, encodedTag, clickEvent = null) {
  clickEvent?.preventDefault();
  clickEvent?.stopPropagation();
  const assetId = decodeURIComponent(encodedAssetId);
  const tag = decodeURIComponent(encodedTag);
  const asset = assets.find(item => inventoryAssetIdentifier(item) === assetId);
  if (!asset || !currentUser?.isAdmin) return;
  const nextTags = normalizeAssetTags(asset.tags).filter(item => item.toLocaleLowerCase() !== tag.toLocaleLowerCase());

  try {
    await apiCall(`/api/assets/${encodeURIComponent(assetId)}`, 'PUT', {
      applyTo: 'single',
      tags: nextTags,
    });
    const detailsWasOpen = document.getElementById('assetDetailsModal')?.classList.contains('active');
    await refreshInventoryAssetsInPlace([assetId]);
    if (detailsWasOpen) openAssetDetailsModal(encodeURIComponent(assetId));
    showNotification('success', `Removed tag ${tag}`);
  } catch (error) {
    showNotification('error', `Failed to remove tag: ${error.message}`);
  }
}

function pruneInventorySelection() {
  const validIds = new Set((assets || []).map(inventoryAssetIdentifier).filter(Boolean));
  Array.from(selectedInventoryAssetIds).forEach(assetId => {
    if (!validIds.has(assetId)) selectedInventoryAssetIds.delete(assetId);
  });
  if (lastInventorySelectionAnchorId && !validIds.has(lastInventorySelectionAnchorId)) {
    lastInventorySelectionAnchorId = '';
  }
}

function getSelectedInventoryAssets() {
  pruneInventorySelection();
  return (assets || []).filter(asset => selectedInventoryAssetIds.has(inventoryAssetIdentifier(asset)));
}

function customAssetDetailText(custom) {
  if (!custom) return '';
  if (custom.type === 'LOAN') return custom.company ? `From ${custom.company}` : '';
  return String(custom.description || '').trim();
}

function openMaintenanceForSelectedInventoryAssets() {
  const selectedAssets = getSelectedInventoryAssets();
  if (!selectedAssets.length) {
    showNotification('warning', 'Select at least one asset to log maintenance');
    return;
  }

  const bulkAssets = selectedAssets.filter(asset => asset.isBulk);
  if (bulkAssets.length) {
    if (selectedAssets.length === 1) {
      openBulkMaintenanceFaultModal(inventoryAssetIdentifier(bulkAssets[0]));
      return;
    }
    showNotification(
      'warning',
      'Bulk stock needs a quantity-specific maintenance log. Select each bulk item separately.'
    );
    return;
  }

  openMaintenanceModal(selectedAssets.map(inventoryAssetIdentifier));
}

function updateInventorySelectionUi(currentVisibleAssets = null) {
  pruneInventorySelection();

  const selectedCount = selectedInventoryAssetIds.size;
  const visibleAssets = currentVisibleAssets || getFilteredInventoryData().filteredAssets || [];
  const visibleIds = visibleAssets.map(inventoryAssetIdentifier).filter(Boolean);
  const selectedVisibleCount = visibleIds.filter(assetId => selectedInventoryAssetIds.has(assetId)).length;
  const countEl = document.getElementById('inventory-selected-count');
  const maintenanceButton = document.getElementById('inventory-bulk-maintenance-button');
  const editButton = document.getElementById('inventory-bulk-edit-button');
  const deleteButton = document.getElementById('inventory-bulk-delete-button');
  const clearButton = document.getElementById('inventory-clear-selection-button');

  if (countEl) {
    countEl.textContent = selectedCount ? `${selectedCount} selected` : 'Select all';
    countEl.disabled = selectedCount === 0 && visibleIds.length === 0;
    countEl.title = selectedCount
      ? `Clear ${selectedCount} selected asset${selectedCount === 1 ? '' : 's'}`
      : `Select all ${visibleIds.length} matching asset${visibleIds.length === 1 ? '' : 's'}`;
    countEl.setAttribute(
      'aria-label',
      selectedCount
        ? `Clear ${selectedCount} selected asset${selectedCount === 1 ? '' : 's'}`
        : `Select all ${visibleIds.length} matching asset${visibleIds.length === 1 ? '' : 's'}`,
    );
  }
  if (maintenanceButton) maintenanceButton.disabled = selectedCount === 0;
  if (editButton) editButton.disabled = selectedCount === 0;
  if (deleteButton) deleteButton.disabled = selectedCount === 0;
  if (clearButton) clearButton.disabled = selectedCount === 0;

  document.querySelectorAll('.inventory-row-select').forEach(input => {
    input.checked = selectedInventoryAssetIds.has(input.dataset.assetId || '');
  });

  const selectAll = document.getElementById('inventory-select-all-current');

  if (selectAll) {
    selectAll.checked = visibleIds.length > 0 && selectedVisibleCount === visibleIds.length;
    selectAll.indeterminate = selectedVisibleCount > 0 && selectedVisibleCount < visibleIds.length;
    selectAll.disabled = visibleIds.length === 0;
  }
}

function inventoryVisibleSelectableAssetIds() {
  return Array.from(document.querySelectorAll('.inventory-row-select'))
    .map(input => String(input.dataset.assetId || '').trim())
    .filter(Boolean);
}

function toggleInventoryAssetSelection(assetId, checked, selectionEvent = null) {
  const normalized = String(assetId || '').trim();
  if (!normalized) return;

  const visibleIds = inventoryVisibleSelectableAssetIds();
  const anchorIndex = visibleIds.indexOf(lastInventorySelectionAnchorId);
  const currentIndex = visibleIds.indexOf(normalized);
  const shouldSelectRange = Boolean(
    selectionEvent?.shiftKey && anchorIndex >= 0 && currentIndex >= 0
  );

  if (shouldSelectRange) {
    const rangeStart = Math.min(anchorIndex, currentIndex);
    const rangeEnd = Math.max(anchorIndex, currentIndex);
    visibleIds.slice(rangeStart, rangeEnd + 1).forEach(id => {
      if (checked) selectedInventoryAssetIds.add(id);
      else selectedInventoryAssetIds.delete(id);
    });
  } else if (checked) {
    selectedInventoryAssetIds.add(normalized);
  } else {
    selectedInventoryAssetIds.delete(normalized);
  }

  lastInventorySelectionAnchorId = normalized;

  updateInventorySelectionUi();
}

function toggleInventorySelectAll(checked) {
  const { filteredAssets } = getFilteredInventoryData();
  filteredAssets.forEach(asset => {
    const assetId = inventoryAssetIdentifier(asset);
    if (!assetId) return;
    if (checked) selectedInventoryAssetIds.add(assetId);
    else selectedInventoryAssetIds.delete(assetId);
  });

  lastInventorySelectionAnchorId = '';
  updateInventorySelectionUi(filteredAssets);
  displayInventoryTable(filteredAssets);
}

function toggleInventorySelectionFromCount() {
  if (selectedInventoryAssetIds.size > 0) {
    clearInventorySelection();
    return;
  }
  toggleInventorySelectAll(true);
}

function clearInventorySelection() {
  selectedInventoryAssetIds.clear();
  lastInventorySelectionAnchorId = '';
  updateInventorySelectionUi();
  displayFilteredInventory();
}

async function loadAssetUsageDays(assetId) {
  const content = document.getElementById('assetDetailsContent');
  const value = document.getElementById('assetDetailsUsageDays');
  if (!content || !value) return;

  try {
    const response = await apiCall(
      `/api/assets/${encodeURIComponent(assetId)}/usage-summary`
    );
    if (content.dataset.assetId !== String(assetId || '')) return;
    const days = Math.max(0, Number(response.data?.usageDays || 0));
    value.textContent = `${days} day${days === 1 ? '' : 's'}`;
  } catch (error) {
    if (content.dataset.assetId === String(assetId || '')) {
      value.textContent = '-';
    }
  }
}

async function openAssetDetailsModal(encodedAssetId) {
  let assetId = String(encodedAssetId || '');
  try {
    assetId = decodeURIComponent(assetId);
  } catch (error) {
    // Keep the original value if it was not URI encoded.
  }

  let asset = getAssetByApiIdentifier(assetId);
  if (!asset) {
    showNotification('error', `Asset ${assetId} not found`);
    return;
  }

  if (!Object.prototype.hasOwnProperty.call(asset, 'changeHistory')) {
    try {
      const apiId = getAssetIdentifierForApi(asset);
      const response = await apiCall(
        `/api/assets?query=${encodeURIComponent(apiId)}&limit=100`
      );
      const fullAsset = (response.data || []).find(row =>
        inventoryAssetMatchesIdentifier(row, apiId)
      );
      if (fullAsset) {
        const index = assets.findIndex(row =>
          inventoryAssetMatchesIdentifier(row, apiId)
        );
        if (index >= 0) assets[index] = fullAsset;
        asset = fullAsset;
      }
    } catch (error) {
      showNotification('error', error.message || 'Unable to load asset details');
      return;
    }
  }

  const modal = document.getElementById('assetDetailsModal');
  const title = document.getElementById('assetDetailsTitle');
  const content = document.getElementById('assetDetailsContent');
  if (!modal || !title || !content) return;

  const apiId = getAssetIdentifierForApi(asset);
  const encodedApiId = encodeURIComponent(apiId);
  const displayId = asset.isBulk ? 'Bulk Item' : (asset.id || apiId);
  content.dataset.assetId = apiId;
  const notes = String(asset.notes || '').trim();
  const degradedReasons = [
    ...(Array.isArray(asset.degradedReasons) ? asset.degradedReasons : []),
    ...(Array.isArray(asset.bulkDegradedReasons) ? asset.bulkDegradedReasons : []),
  ].map(reason => cleanDegradedReasonText(reason)).filter(Boolean);
  const uniqueDegradedReasons = [...new Set(degradedReasons)];
  const bulkStockHtml = asset.isBulk ? `
    <section class="asset-details-section">
      <div class="asset-details-section-heading"><h4>Bulk stock</h4><span>Quantity and deployment information</span></div>
      <div class="asset-details-grid asset-details-stock-grid">
        <div class="asset-details-field"><span>Total quantity</span><strong>${escapeHtml(String(asset.quantity ?? 1))}</strong></div>
        <div class="asset-details-field"><span>Available</span><strong>${escapeHtml(String(asset.availableQuantity ?? asset.quantity ?? 1))}</strong></div>
        <div class="asset-details-field"><span>Preparable</span><strong>${escapeHtml(String(asset.preparableQuantity ?? asset.availableQuantity ?? asset.quantity ?? 1))}</strong></div>
        <div class="asset-details-field"><span>Healthy</span><strong>${escapeHtml(String(asset.healthyQuantity ?? asset.availableQuantity ?? asset.quantity ?? 1))}</strong></div>
        <div class="asset-details-field"><span>Deployed</span><strong>${escapeHtml(String(asset.deployedQuantity ?? 0))}</strong></div>
        <div class="asset-details-field"><span>OOC / missing / degraded</span><strong>${escapeHtml(`${asset.bulkOOCQuantity || 0} / ${asset.bulkMissingQuantity || 0} / ${asset.bulkDegradedQuantity || 0}`)}</strong></div>
      </div>
      ${bulkDeploymentDetailsHtml(asset)}
    </section>
  ` : '';

  title.textContent = `${asset.isBulk ? 'Bulk Asset' : 'Asset'} Details`;
  content.innerHTML = `
    <div class="modal-body asset-details-body">
      <div class="asset-details-identity">
        <div class="asset-details-identity-label"><span>${asset.isBulk ? 'Bulk stock record' : 'Asset ID'}</span></div>
        <div class="asset-details-identity-record">
          <div><strong>${escapeHtml(displayId)}</strong>${asset.isBulk ? `<small>Internal ID: ${escapeHtml(apiId)}</small>` : ''}</div>
          <div class="asset-details-product"><div class="asset-details-product-heading"><strong>${escapeHtml([asset.brand, asset.model].filter(Boolean).join(' ') || '-')}</strong>${departmentBadgeHtml(asset.department)}</div><span>${escapeHtml(asset.description || '-')}</span>${inventoryAssetTagsHtml(asset, isAdminUser())}</div>
        </div>
      </div>

      <section class="asset-details-section">
        <div class="asset-details-section-heading"><h4>Asset information</h4><span>Serial numbers and dates</span></div>
        <div class="asset-details-grid">
          ${asset.isBulk ? '' : `
            <div class="asset-details-field"><span>Primary serial number</span><strong>${escapeHtml(asset.serial || '-')}</strong></div>
            <div class="asset-details-field"><span>Secondary serial number</span><strong>${escapeHtml(asset.serial2 || '-')}</strong></div>
          `}
          <div class="asset-details-field"><span>Version</span><strong>${escapeHtml(asset.version || '-')}</strong></div>
          <div class="asset-details-field"><span>Date purchased</span><strong>${escapeHtml(formatAssetPurchaseDate(asset.dateOfPurchase || asset.purchaseDate || '') || '-')}</strong></div>
          <div class="asset-details-field"><span>Date added</span><strong>${escapeHtml(formatAssetAuditDateTime(asset.dateAdded || '') || '-')}</strong></div>
          <div class="asset-details-field"><span>Last modified</span><strong>${escapeHtml(formatAssetAuditDateTime(asset.dateModified || '') || '-')}</strong></div>
          <div class="asset-details-field"><span>Days used</span><strong id="assetDetailsUsageDays" aria-live="polite">Calculating...</strong></div>
        </div>
      </section>

      <section class="asset-details-section">
        <div class="asset-details-section-heading"><h4>Status and location</h4><span>Current operational state</span></div>
        <div class="asset-details-grid asset-details-operational-grid">
          <div class="asset-details-field"><span>Availability</span><strong>${inventoryAvailabilityBadgesHtml(asset)}</strong></div>
          <div class="asset-details-field"><span>Condition</span><strong>${assetFlagBadgesHtml(asset)}</strong></div>
          <div class="asset-details-field"><span>Default location</span><strong>${escapeHtml(asset.defaultLocation || '-')}</strong></div>
          <div class="asset-details-field"><span>Current location</span><strong>${escapeHtml(asset.currentLocation || '-')}</strong></div>
        </div>
        ${uniqueDegradedReasons.length ? `<div class="asset-details-reasons"><strong>Degraded reason${uniqueDegradedReasons.length === 1 ? '' : 's'}</strong><ul>${uniqueDegradedReasons.map(reason => `<li>${escapeHtml(reason)}</li>`).join('')}</ul></div>` : ''}
      </section>

      ${bulkStockHtml}

      <section class="asset-details-section">
        <div class="asset-details-section-heading"><h4>Notes</h4><span>Asset-specific information</span></div>
        <div class="asset-details-notes ${notes ? '' : 'is-empty'}">${notes ? escapeHtml(notes) : '-'}</div>
      </section>

      <section class="asset-details-section asset-details-history">
        <div class="asset-details-section-heading"><h4>Edit history</h4><span>${Array.isArray(asset.changeHistory) ? asset.changeHistory.length : 0} recorded change${Array.isArray(asset.changeHistory) && asset.changeHistory.length === 1 ? '' : 's'}</span></div>
        <div class="asset-details-history-list">${assetChangeHistoryHtml(asset)}</div>
      </section>

      <div class="modal-actions asset-details-actions">
        <button type="button" class="btn btn-primary" onclick="closeModal('assetDetailsModal'); viewMaintenanceLog('${escapeHtmlAttr(encodedApiId)}')">View Log</button>
        ${
          isAdminUser()
            ? `<button type="button" class="btn btn-warning" onclick="closeModal('assetDetailsModal'); openEditAssetModal('${escapeHtmlAttr(encodedApiId)}')">Edit Asset</button>`
            : ''
        }
        <button type="button" class="btn btn-secondary" onclick="closeModal('assetDetailsModal')">Close</button>
      </div>
    </div>
  `;

  openModal('assetDetailsModal');
  loadAssetUsageDays(apiId);
}

