function inventoryAssetQuantity(asset) {
  return asset?.isBulk ? Math.max(1, Number(asset.quantity || 1) || 1) : 1;
}

function inventoryConditionCounts(assetList) {
  const counts = { available: 0, untagged: 0, degraded: 0, ooc: 0, missing: 0, decommissioned: 0 };
  (assetList || []).forEach(asset => {
    const total = inventoryAssetQuantity(asset);
    if (!asset?.isBulk) {
      counts[getAssetConditionStatus(asset)] += 1;
      return;
    }

    const wholeStatus = getAssetConditionStatus(asset);
    if (wholeStatus === 'decommissioned') {
      counts.decommissioned += total;
      return;
    }

    let remaining = total;
    let wholeStatusHasExplicitQuantity = false;
    ['ooc', 'missing', 'degraded'].forEach(status => {
      const field = status === 'ooc' ? 'bulkOOCQuantity' : status === 'missing' ? 'bulkMissingQuantity' : 'bulkDegradedQuantity';
      const amount = Math.min(remaining, Math.max(0, Number(asset[field] || 0) || 0));
      counts[status] += amount;
      remaining -= amount;
      if (status === wholeStatus && amount > 0) wholeStatusHasExplicitQuantity = true;
    });
    if (wholeStatus !== 'available' && !wholeStatusHasExplicitQuantity) {
      counts[wholeStatus] += remaining;
      remaining = 0;
    }
    counts.available += remaining;
  });
  return counts;
}

function inventoryAvailabilityCounts(assetList) {
  const counts = {
    available: 0,
    untaggedAvailable: 0,
    degradedAvailable: 0,
    deployed: 0,
    ooc: 0,
    missing: 0,
    decommissioned: 0,
    total: 0
  };

  (assetList || []).forEach(asset => {
    const total = inventoryAssetQuantity(asset);
    const condition = getAssetConditionStatus(asset);
    counts.total += total;

    if (!asset?.isBulk) {
      if (condition === 'decommissioned') counts.decommissioned += 1;
      else if (condition === 'missing') counts.missing += 1;
      else if (condition === 'ooc') counts.ooc += 1;
      else if (asset.status === 'deployed' || Number(asset.deployedQuantity || 0) > 0) counts.deployed += 1;
      else {
        counts.available += 1;
        if (condition === 'untagged') counts.untaggedAvailable += 1;
        if (condition === 'degraded') counts.degradedAvailable += 1;
      }
      return;
    }

    if (condition === 'decommissioned') {
      counts.decommissioned += total;
      return;
    }

    const deployed = Math.min(total, Math.max(0, Number(asset.deployedQuantity || 0) || 0));
    counts.deployed += deployed;
    let remaining = total - deployed;

    if (asset.isMissing) {
      counts.missing += remaining;
      return;
    }
    if (asset.isOOC) {
      counts.ooc += remaining;
      return;
    }

    const missing = Math.min(remaining, Math.max(0, Number(asset.bulkMissingQuantity || 0) || 0));
    counts.missing += missing;
    remaining -= missing;
    const ooc = Math.min(remaining, Math.max(0, Number(asset.bulkOOCQuantity || 0) || 0));
    counts.ooc += ooc;
    remaining -= ooc;

    counts.available += remaining;
    const degraded = asset.isDegraded
      ? remaining
      : Math.min(remaining, Math.max(0, Number(asset.bulkDegradedQuantity || 0) || 0));
    counts.degradedAvailable += degraded;
  });

  return counts;
}

function inventoryAvailabilityChartHtml(counts, compact = false) {
  const segmentsByStatus = {
    available: Math.max(0, counts.available - counts.untaggedAvailable - counts.degradedAvailable),
    untagged: counts.untaggedAvailable,
    degraded: counts.degradedAvailable,
    deployed: counts.deployed,
    ooc: counts.ooc,
    missing: counts.missing,
    decommissioned: counts.decommissioned
  };
  const total = counts.total || Object.values(segmentsByStatus).reduce((sum, value) => sum + value, 0);
  let cursor = 0;
  const segments = Object.entries(INVENTORY_AVAILABILITY_META).map(([status, meta]) => {
    const start = cursor;
    cursor += total ? (segmentsByStatus[status] / total) * 100 : 0;
    return `${meta.color} ${start.toFixed(2)}% ${cursor.toFixed(2)}%`;
  }).join(', ');
  const visible = Object.entries(INVENTORY_AVAILABILITY_META).filter(
    ([status]) => segmentsByStatus[status] > 0
  );
  return `
    <div class="inventory-donut" style="--donut-background:${total ? `conic-gradient(${segments})` : '#e5ece9'}">
      <div class="inventory-donut-centre"><strong>${total}</strong>${compact ? 'assets' : 'total'}</div>
    </div>
    <div class="inventory-condition-legend">
      ${visible.map(([status, meta]) => `
        <div class="inventory-condition-key" style="--key-color:${meta.color}">
          <i></i><span>${meta.label}</span><strong>${segmentsByStatus[status]}</strong>
        </div>
      `).join('') || '<span style="color:#64748b;font-size:11px">No assets</span>'}
    </div>
  `;
}

function inventoryConditionChartHtml(counts, compact = false) {
  const total = Object.values(counts).reduce((sum, value) => sum + value, 0);
  let cursor = 0;
  const segments = Object.entries(INVENTORY_CONDITION_META).map(([status, meta]) => {
    const start = cursor;
    cursor += total ? (counts[status] / total) * 100 : 0;
    return `${meta.color} ${start.toFixed(2)}% ${cursor.toFixed(2)}%`;
  }).join(', ');
  const visible = Object.entries(INVENTORY_CONDITION_META).filter(([status]) => counts[status] > 0);
  return `
    <div class="inventory-donut" style="--donut-background:${total ? `conic-gradient(${segments})` : '#e5ece9'}">
      <div class="inventory-donut-centre"><strong>${total}</strong>${compact ? 'assets' : 'total'}</div>
    </div>
    <div class="inventory-condition-legend">
      ${visible.map(([status, meta]) => `
        <div class="inventory-condition-key" style="--key-color:${meta.color}">
          <i></i><span>${meta.label}</span><strong>${counts[status]}</strong>
        </div>
      `).join('') || '<span style="color:#64748b;font-size:11px">No assets</span>'}
    </div>
  `;
}

function inventoryAssetGroupKey(asset) {
  return [
    normalizeDepartmentCode(asset?.department || 'UN'),
    String(asset?.brand || '').trim(),
    String(asset?.model || '').trim(),
    String(asset?.description || '').trim()
  ]
    .join('\u001f');
}

function groupInventoryAssets(assetList) {
  const groups = new Map();
  (assetList || []).forEach(asset => {
    const key = inventoryAssetGroupKey(asset);
    if (!groups.has(key)) groups.set(key, {
      key,
      assets: [],
      brand: asset.brand || '-',
      model: asset.model || '-',
      description: String(asset.description || '').trim(),
      department: asset.department || 'UN'
    });
    groups.get(key).assets.push(asset);
  });
  return Array.from(groups.values());
}

function inventoryLatestMaintenance(assetList) {
  let latest = null;
  (assetList || []).forEach(asset => {
    getMaintenanceLogRecords(asset).forEach((record, originalIndex) => {
      const candidate = {
        ...record,
        originalIndex,
        timestamp: maintenanceLogDateSortValue(record.date),
        createdTimestamp: maintenanceLogCreatedSortValue(record.createdAt)
      };
      if (!latest || compareMaintenanceLogsNewestFirst(candidate, latest) < 0) {
        latest = candidate;
      }
    });
  });
  return latest;
}

function inventoryMaintenanceDateText(record) {
  if (!record?.date) return '-';
  const raw = String(record.date);
  const match = raw.match(/^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})/);
  if (!match) return raw;
  const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
  return date.toLocaleDateString('en-SG', { day: 'numeric', month: 'short', year: 'numeric' });
}

function inventoryGroupDescription(group) {
  return String(group?.description || '').trim() || '-';
}

function inventoryStatusHistoryRecord(asset, status) {
  const cleanStatus = String(status || '').trim().toLowerCase();
  if (!asset || !cleanStatus || cleanStatus === 'available' || cleanStatus === 'deployed') return null;

  const activeBulkRecords = (Array.isArray(asset.bulkMaintenanceLogbook)
    ? asset.bulkMaintenanceLogbook
    : [])
    .filter(row => !row?.isResolved && String(row?.status || '').toLowerCase() === cleanStatus)
    .map((row, originalIndex) => ({
      ...normalizeMaintenanceLogRecord(row.fault),
      originalIndex
    }))
    .sort(compareMaintenanceLogsNewestFirst);
  if (activeBulkRecords.length) return activeBulkRecords[0];

  const records = getMaintenanceLogRecords(asset)
    .map((record, originalIndex) => ({ ...record, originalIndex }))
    .sort(compareMaintenanceLogsNewestFirst);
  for (const record of records) {
    for (let index = record.changes.length - 1; index >= 0; index--) {
      const change = normalizeMaintenanceChange(record.changes[index]);
      if (!change || change.kind !== cleanStatus) continue;
      return change.action === 'marked' ? record : null;
    }
    const source = record.source || {};
    if (
      String(source.kind || '').toLowerCase() === 'bulk_maintenance_fault'
      && String(source.bulkStatus || '').toLowerCase() === cleanStatus
    ) return record;
  }
  return null;
}

function ensureInventoryStatusHistoryTooltip() {
  let tooltip = document.getElementById('inventoryStatusHistoryTooltip');
  if (tooltip) return tooltip;
  tooltip = document.createElement('div');
  tooltip.id = 'inventoryStatusHistoryTooltip';
  tooltip.className = 'pnl-chart-tooltip inventory-status-tooltip';
  tooltip.setAttribute('role', 'status');
  tooltip.setAttribute('aria-live', 'polite');
  tooltip.innerHTML = '<i aria-hidden="true"></i><div><strong></strong><span></span><em></em></div>';
  document.body.appendChild(tooltip);
  return tooltip;
}

let inventoryStatusTooltipPinned = false;

function inventoryPositionStatusHistoryTooltip(event, target) {
  const tooltip = document.getElementById('inventoryStatusHistoryTooltip');
  if (!tooltip || !target) return;
  const rect = target.getBoundingClientRect();
  const eventX = Number(event?.clientX);
  const xAnchor = Number.isFinite(eventX) && eventX > 0
    ? eventX
    : rect.left + rect.width / 2;
  const below = rect.top < 105;
  const width = Math.max(120, tooltip.offsetWidth || 240);
  const x = Math.min(Math.max(xAnchor, width / 2 + 8), window.innerWidth - width / 2 - 8);
  tooltip.style.left = `${x}px`;
  tooltip.style.top = `${below ? rect.bottom : rect.top}px`;
  tooltip.classList.toggle('is-below', below);
}

function inventoryShowStatusHistoryTooltip(event, target, encodedAssetId, status) {
  let assetId = String(encodedAssetId || '');
  try { assetId = decodeURIComponent(assetId); } catch (error) {}
  const asset = getAssetByApiIdentifier(assetId);
  const record = inventoryStatusHistoryRecord(asset, status);
  if (!record) return;
  const tooltip = ensureInventoryStatusHistoryTooltip();
  tooltip.innerHTML = '<i aria-hidden="true"></i><div><strong></strong><span></span><em></em></div>';
  const statusMeta = INVENTORY_CONDITION_META[status] || { label: inventoryStatusText(status), color: '#334155' };
  tooltip.querySelector('strong').textContent = `Marked ${statusMeta.label}`;
  tooltip.querySelector('span').textContent = `${maintenanceLogUserLabel(record) || 'Unknown person'} · ${inventoryMaintenanceDateText(record)}`;
  const description = record.description || 'No description recorded.';
  tooltip.querySelector('em').innerHTML = maintenanceDescriptionHtml(
    description,
    { interactive: false }
  );
  tooltip.style.setProperty('--tooltip-colour', statusMeta.color || '#334155');
  tooltip.classList.add('is-visible');
  inventoryPositionStatusHistoryTooltip(event, target);
}

function inventoryHideStatusHistoryTooltip(force = false) {
  if (inventoryStatusTooltipPinned && !force) return;
  inventoryStatusTooltipPinned = false;
  document.getElementById('inventoryStatusHistoryTooltip')?.classList.remove('is-visible', 'is-below');
}

function inventoryDeploymentRecords(asset) {
  const rows = Array.isArray(asset?.deployments)
    ? asset.deployments
    : Array.isArray(asset?.bulkDeployments)
      ? asset.bulkDeployments
      : [];
  return rows.filter(row => row && Number(row.quantity || 0) > 0);
}

function inventoryShowDeploymentTooltip(event, target, encodedAssetId) {
  let assetId = String(encodedAssetId || '');
  try { assetId = decodeURIComponent(assetId); } catch (error) {}
  const asset = getAssetByApiIdentifier(assetId);
  const deployments = inventoryDeploymentRecords(asset);
  if (!deployments.length) return;

  const tooltip = ensureInventoryStatusHistoryTooltip();
  const eventLabel = deployments.length === 1 ? 'Deployed to' : `Deployed to ${deployments.length} events`;
  tooltip.innerHTML = `
    <i aria-hidden="true"></i>
    <div>
      <strong>${escapeHtml(eventLabel)}</strong>
      <div class="inventory-deployment-tooltip-list">
        ${deployments.map(deployment => {
          const eventName = deployment.eventName || (deployment.eventId ? `Event ${deployment.eventId}` : 'Event');
          const eventId = deployment.eventId ? `#${deployment.eventId}` : '';
          const dateText = bulkDeploymentDateText(deployment) || 'Date not set';
          const quantity = Math.max(1, Number(deployment.quantity || 1) || 1);
          const quantityText = asset?.isBulk ? `${quantity} deployed` : '1 asset';
          return `<button type="button" class="inventory-deployment-tooltip-row" onclick="inventoryOpenDeploymentEvent(event,${Number(deployment.eventId) || 0})"><span><b>${escapeHtml(eventId)}</b>${escapeHtml(eventName)}</span><em>${escapeHtml(dateText)} &middot; ${escapeHtml(quantityText)}</em></button>`;
        }).join('')}
      </div>
    </div>`;
  tooltip.style.setProperty('--tooltip-colour', ASSET_DEPLOYED_COLOR);
  tooltip.classList.add('is-visible');
  inventoryPositionStatusHistoryTooltip(event, target);
}

function inventoryOpenDeploymentEvent(clickEvent, eventId) {
  clickEvent?.preventDefault();
  clickEvent?.stopPropagation();
  const numericEventId = Number(eventId);
  if (!numericEventId) return;
  inventoryHideStatusHistoryTooltip(true);
  viewEvent(numericEventId);
}

function inventoryActivateDeployment(clickEvent, target, encodedAssetId) {
  clickEvent?.preventDefault();
  clickEvent?.stopPropagation();
  let assetId = String(encodedAssetId || '');
  try { assetId = decodeURIComponent(assetId); } catch (error) {}
  const deployments = inventoryDeploymentRecords(getAssetByApiIdentifier(assetId));
  if (deployments.length === 1) {
    inventoryOpenDeploymentEvent(clickEvent, deployments[0].eventId);
    return;
  }
  if (!deployments.length) return;
  inventoryStatusTooltipPinned = true;
  inventoryShowDeploymentTooltip(clickEvent, target, encodedAssetId);
}

function inventoryDeploymentBadgeHtml(asset, label) {
  const badge = statusBadgeHtml('deployed', label);
  const deployments = inventoryDeploymentRecords(asset);
  if (!deployments.length) return badge;
  const encodedId = encodeURIComponent(inventoryAssetIdentifier(asset));
  const accessibleEvents = deployments.map(deployment => {
    const eventName = deployment.eventName || (deployment.eventId ? `Event ${deployment.eventId}` : 'Event');
    return `${deployment.eventId ? `Event ${deployment.eventId}: ` : ''}${eventName}`;
  }).join('; ');
  return `<button type="button" class="inventory-status-history inventory-deployment-status" aria-label="${escapeHtmlAttr(`${label}. ${accessibleEvents}`)}" onclick="inventoryActivateDeployment(event,this,'${escapeHtmlAttr(encodedId)}')"
    onpointerenter="inventoryShowDeploymentTooltip(event,this,'${escapeHtmlAttr(encodedId)}')"
    onpointermove="inventoryPositionStatusHistoryTooltip(event,this)"
    onpointerleave="inventoryHideStatusHistoryTooltip()"
    onfocus="inventoryShowDeploymentTooltip(event,this,'${escapeHtmlAttr(encodedId)}')"
    onblur="inventoryHideStatusHistoryTooltip()"
    onkeydown="if(event.key==='Escape'){inventoryHideStatusHistoryTooltip(true);this.blur();}">${badge}</button>`;
}

function inventoryOpenStatusMaintenance(clickEvent, encodedAssetId) {
  clickEvent?.preventDefault();
  clickEvent?.stopPropagation();
  inventoryHideStatusHistoryTooltip(true);
  viewMaintenanceLog(encodedAssetId);
}

function inventoryStatusHistoryBadgeHtml(asset, status, label) {
  const badge = statusBadgeHtml(status, label);
  const record = inventoryStatusHistoryRecord(asset, status);
  if (!record) return badge;
  const encodedId = encodeURIComponent(inventoryAssetIdentifier(asset));
  const accessibleDescription = maintenanceDescriptionPlainText(
    record.description || 'No description recorded.'
  );
  const accessible = `${label}. Marked by ${maintenanceLogUserLabel(record) || 'Unknown person'} on ${inventoryMaintenanceDateText(record)}. ${accessibleDescription}`;
  const isMaintenanceAction = status === 'ooc' || status === 'degraded';
  const tagName = isMaintenanceAction ? 'button' : 'span';
  const buttonAttributes = isMaintenanceAction
    ? `type="button" onclick="inventoryOpenStatusMaintenance(event,'${escapeHtmlAttr(encodedId)}')"`
    : 'tabindex="0"';
  return `<${tagName} class="inventory-status-history" ${buttonAttributes} aria-label="${escapeHtmlAttr(accessible)}"
    onpointerenter="inventoryShowStatusHistoryTooltip(event,this,'${escapeHtmlAttr(encodedId)}','${escapeHtmlAttr(status)}')"
    onpointermove="inventoryPositionStatusHistoryTooltip(event,this)"
    onpointerleave="inventoryHideStatusHistoryTooltip()"
    onfocus="inventoryShowStatusHistoryTooltip(event,this,'${escapeHtmlAttr(encodedId)}','${escapeHtmlAttr(status)}')"
    onblur="inventoryHideStatusHistoryTooltip()"
    onkeydown="if(event.key==='Escape'){inventoryHideStatusHistoryTooltip(true);this.blur();}">${badge}</${tagName}>`;
}

function inventoryAvailabilityBadgesHtml(asset, includeStatusHistory = false) {
  const counts = inventoryAvailabilityCounts([asset]);
  const badges = [];
  const withQuantity = (value, label) => `${counts.total > 1 ? `${value} ` : ''}${label}`;
  const conditionBadge = (status, label) => includeStatusHistory
    ? inventoryStatusHistoryBadgeHtml(asset, status, label)
    : statusBadgeHtml(status, label);

  if (counts.deployed > 0) badges.push(inventoryDeploymentBadgeHtml(asset, withQuantity(counts.deployed, 'Deployed')));
  if (counts.ooc > 0) badges.push(conditionBadge('ooc', withQuantity(counts.ooc, 'OOC')));
  if (counts.missing > 0) badges.push(conditionBadge('missing', withQuantity(counts.missing, 'Missing')));
  if (counts.decommissioned > 0) badges.push(conditionBadge('decommissioned', withQuantity(counts.decommissioned, 'Decommissioned')));

  const clearAvailable = Math.max(0, counts.available - counts.untaggedAvailable - counts.degradedAvailable);
  if (clearAvailable > 0) badges.push(statusBadgeHtml('available', withQuantity(clearAvailable, 'OK')));
  if (counts.untaggedAvailable > 0) {
    badges.push(conditionBadge('untagged', withQuantity(counts.untaggedAvailable, 'Untagged')));
  } else if (counts.deployed > 0 && getAssetConditionStatus(asset) === 'untagged') {
    badges.push(conditionBadge('untagged', 'Untagged'));
  }
  if (counts.degradedAvailable > 0) {
    badges.push(conditionBadge('degraded', withQuantity(counts.degradedAvailable, 'Degraded')));
  } else if (counts.deployed > 0 && getAssetConditionStatus(asset) === 'degraded') {
    badges.push(conditionBadge('degraded', 'Degraded'));
  }

  return badges.join(' ') || statusBadgeHtml('available', 'OK');
}

function inventoryIndividualRowHtml(asset, isAdmin) {
  const assetId = inventoryAssetIdentifier(asset);
  const encodedId = encodeURIComponent(assetId);
  const total = inventoryAssetQuantity(asset);
  const availabilityHtml = inventoryAvailabilityBadgesHtml(asset, true);
  const maintenance = inventoryLatestMaintenance([asset]);
  return `
    <div class="inventory-individual-row">
      ${isAdmin ? `<input type="checkbox" class="inventory-row-select" data-asset-id="${escapeHtmlAttr(assetId)}" ${selectedInventoryAssetIds.has(assetId) ? 'checked' : ''} onclick="toggleInventoryAssetSelection(this.dataset.assetId,this.checked,event)" aria-label="Select ${escapeHtmlAttr(assetId)}">` : '<span></span>'}
      <div><span class="inventory-individual-id">${escapeHtml(asset.isBulk ? 'Bulk stock' : assetId)}</span><span class="inventory-individual-meta" style="display:block">${escapeHtml(asset.isBulk ? `${total} units` : (asset.serial || '-'))}</span></div>
      <div class="inventory-individual-meta inventory-individual-version">${escapeHtml(asset.version || '-')}</div>
      <div>${availabilityHtml}</div>
      <div class="inventory-individual-meta">${escapeHtml(asset.currentLocation || asset.location || '-')}</div>
      <div class="inventory-individual-meta">${escapeHtml(inventoryMaintenanceDateText(maintenance))}</div>
      <div class="inventory-individual-actions">
        <button type="button" class="inventory-icon-button" onclick="openAssetDetailsModal('${escapeHtmlAttr(encodedId)}')" title="View asset" aria-label="View asset">${inventoryIcon('eye')}</button>
        <button type="button" class="inventory-icon-button" onclick="viewMaintenanceLog('${escapeHtmlAttr(encodedId)}')" title="View past logs" aria-label="View past logs">${inventoryIcon('wrench')}</button>
        ${isAdmin ? `<button type="button" class="inventory-icon-button" onclick="openEditAssetModal('${escapeHtmlAttr(encodedId)}')" title="Edit asset" aria-label="Edit asset">${inventoryIcon('edit')}</button>` : ''}
      </div>
    </div>
  `;
}

function toggleInventoryModelGroup(encodedKey) {
  const key = decodeURIComponent(encodedKey);
  if (expandedInventoryModelKeys.has(key)) expandedInventoryModelKeys.delete(key);
  else expandedInventoryModelKeys.add(key);
  displayFilteredInventory();
}

function renderInventorySummary() {
  const sourceAssets = Array.isArray(assets) ? assets : [];
  const conditionCounts = inventoryConditionCounts(sourceAssets);
  const availability = inventoryAvailabilityCounts(sourceAssets);
  const total = availability.total;
  const attention = conditionCounts.untagged + conditionCounts.degraded + conditionCounts.ooc + conditionCounts.missing;
  const modelCount = groupInventoryAssets(sourceAssets).length;
  const attentionDetails = [
    conditionCounts.untagged > 0 ? `${conditionCounts.untagged} untagged` : '',
    conditionCounts.degraded > 0 ? `${conditionCounts.degraded} degraded` : '',
    conditionCounts.ooc > 0 ? `${conditionCounts.ooc} OOC` : '',
    conditionCounts.missing > 0 ? `${conditionCounts.missing} missing` : ''
  ].filter(Boolean).join(', ');
  const cards = [
    ['box', availability.deployed, 'Assets deployed', total ? `${Math.round(availability.deployed / total * 100)}% of total stock` : `${modelCount} brand/model groups`, ASSET_DEPLOYED_COLOR, ASSET_DEPLOYED_SOFT_COLOR],
    ['check', availability.available, 'Available for use', availability.degradedAvailable > 0 ? `${availability.degradedAvailable} degraded available` : (total ? `${Math.round(availability.available / total * 100)}% of stock` : 'No stock'), '#138a5b', '#e7f6ee'],
    ['alert', attention, 'Needs attention', attentionDetails || 'No flagged assets', '#bc7a0a', '#fff3df'],
    ['wrench', conditionCounts.ooc, 'Out of commission', total ? `${Math.round(conditionCounts.ooc / total * 100)}% of stock` : 'No stock', '#b43741', '#fdebed']
  ];
  const grid = document.getElementById('inventory-summary-grid');
  if (grid) grid.innerHTML = cards.map(([icon, value, label, note, color, bg]) => `
    <div class="inventory-stat">
      <span class="inventory-stat-mark" style="--stat-color:${color};--stat-bg:${bg}">${inventoryIcon(icon)}</span>
      <span><strong class="inventory-stat-value">${value}</strong><span class="inventory-stat-label">${label}</span><span class="inventory-stat-note">${note}</span></span>
    </div>
  `).join('');
  const chart = document.getElementById('inventory-overview-chart');
  if (chart) chart.innerHTML = inventoryAvailabilityChartHtml(availability);
}

function displayInventoryTable(assetsToShow) {
  const container = document.getElementById("inventory-table-container");
  if (!container) return;

  if (assetsToShow.length === 0) {
    destroyVirtualTable('inventory');
    container.innerHTML = isAdminUser() ? `
      <div class="inventory-onboarding-empty">
        <div class="inventory-empty">
          <strong style="display:block;color:#172b26;margin-bottom:5px">No matching assets</strong>
          <span style="display:block;margin-bottom:14px">Adjust the filters or add an asset.</span>
          <button type="button" class="btn btn-primary" onclick="openModal('addAssetModal')">Add Asset</button>
        </div>
      </div>
    ` : '<div class="inventory-empty">No matching assets.</div>';
    updateInventorySelectionUi([]);
    return;
  }

  destroyVirtualTable('inventory');
  const isAdmin = !!(currentUser && currentUser.isAdmin);
  const groups = groupInventoryAssets(assetsToShow);
  container.innerHTML = `
    <div class="inventory-catalogue">
      <div class="inventory-model-head"><span>Brand / model</span><span>Description</span><span>Department</span><span>Availability</span><span>Last maintenance</span><span></span></div>
      ${groups.map(group => {
        const encodedKey = encodeURIComponent(group.key);
        const expanded = expandedInventoryModelKeys.has(group.key);
        const availability = inventoryAvailabilityCounts(group.assets);
        const degradedMarker = availability.degradedAvailable > 0 ? '*' : '';
        const latest = inventoryLatestMaintenance(group.assets);
        return `
          <section class="inventory-model-group">
            <button type="button" class="inventory-model-summary" aria-expanded="${expanded}" data-group-key="${escapeHtmlAttr(encodedKey)}" onclick="toggleInventoryModelGroup(this.dataset.groupKey)">
              <span class="inventory-model-name"><strong>${escapeHtml(group.brand)} ${escapeHtml(group.model)}</strong><span>${group.assets.length} inventory record${group.assets.length === 1 ? '' : 's'}</span></span>
              <span class="inventory-model-description">${escapeHtml(inventoryGroupDescription(group))}</span>
              <span>${departmentBadgeHtml(group.department)}</span>
              <span class="inventory-model-quantity" title="${availability.degradedAvailable > 0 ? `Includes ${availability.degradedAvailable} degraded asset${availability.degradedAvailable === 1 ? '' : 's'}` : 'Available for use'}"><strong>${availability.available}${degradedMarker}/${availability.total}</strong><span>assets available</span></span>
              <span class="inventory-last-maintenance">${escapeHtml(inventoryMaintenanceDateText(latest))}<span>${latest?.type ? escapeHtml(inventoryStatusText(latest.type)) : ''}</span></span>
              <span class="inventory-chevron">${inventoryIcon('chevron')}</span>
            </button>
            ${expanded ? `
              <div class="inventory-model-detail">
                <div class="inventory-group-condition"><h4>Availability overview</h4>${inventoryAvailabilityChartHtml(availability, true)}</div>
                <div class="inventory-individual-list">
                  <div class="inventory-individual-head"><span></span><span>Asset ID</span><span>Version</span><span>Availability</span><span>Location</span><span>Last maintenance</span><span></span></div>
                  ${group.assets.map(asset => inventoryIndividualRowHtml(asset, isAdmin)).join('')}
                </div>
              </div>
            ` : ''}
          </section>
        `;
      }).join('')}
    </div>
  `;

  updateInventorySelectionUi(assetsToShow);
}

function normalizeAssetGroupValue(value, uppercase = false) {
  const cleaned = String(value ?? '').trim();
  return uppercase ? cleaned.toUpperCase() : cleaned;
}

function sameAssetGroup(asset, group) {
  return inventoryAssetGroupKey(asset) === inventoryAssetGroupKey(group);
}

