async function loadReturnWorkspace(options = {}) {
  const root = document.getElementById('return-page-root');
  if (!root) return;
  const snapshot = options.preservePosition === false ? null : returnPageCaptureViewState();
  const version = ++returnPageState.requestVersion;
  if (!returnPageState.loaded) {
    root.innerHTML = '<div class="loading">Loading return workspace...</div>';
  }

  try {
    if (!returnPageState.eventId) returnPageState.eventId = workflowRememberedEventId();
    const eventOptionsLoad = await startProgressiveEventOptions(
      returnPageState.eventId,
      loaded => {
        returnPageState.events = loaded;
        returnPageUpdatePickerOptions();
      }
    );
    if (version !== returnPageState.requestVersion) return;
    returnPageState.events = eventOptionsLoad.first;
    eventOptionsLoad.completion.then(loaded => {
      if (version !== returnPageState.requestVersion) return;
      returnPageState.events = loaded;
      returnPageUpdatePickerOptions();
    }).catch(error => console.warn('Unable to load more event options:', error));
    events = returnPageState.events;
    updateOverdueCounter(countOverdueEvents(returnPageState.events));

    const eligible = returnPageEligibleEvents().filter(event => (
      getEventReturnableCount(event) > 0 && event.state !== 'Closed'
    ));
    const keepCurrent = options.keepSelection !== false &&
      returnPageState.eventId &&
      returnPageState.events.some(event => Number(event.id) === Number(returnPageState.eventId));
    const selected = keepCurrent
      ? returnPageState.events.find(event => Number(event.id) === Number(returnPageState.eventId))
      : (eligible[0] || returnPageSelectableEvents()[0]);

    if (!selected) {
      returnPageState.eventId = null;
      returnPageState.event = null;
      returnPageState.loaded = true;
      renderReturnPage({ snapshot });
      return;
    }

    const detailResponse = await apiCall(`/api/events/${selected.id}`);
    if (version !== returnPageState.requestVersion) return;
    returnPageState.eventId = Number(selected.id);
    workflowRememberEvent(selected.id);
    returnPageState.event = detailResponse.data;
    returnPageUpsertEventSummary(detailResponse.data);
    returnPageState.loaded = true;
    renderReturnPage({ snapshot });
  } catch (error) {
    if (version !== returnPageState.requestVersion) return;
    root.innerHTML = `
      <div class="return-empty">
        Failed to load Return: ${escapeHtml(error.message || String(error))}
        <br><br>
        <button type="button" class="return-button return-button-primary" onclick="loadReturnEvents()">Retry</button>
      </div>
    `;
  }
}

async function returnPageSelectEvent(eventId) {
  const id = Number(eventId);
  if (!id || id === Number(returnPageState.eventId)) return;
  const version = ++returnPageState.requestVersion;
  returnPageState.department = 'ALL';
  returnPageState.search = '';
  try {
    const response = await apiCall(`/api/events/${id}`);
    if (version !== returnPageState.requestVersion) return;
    returnPageState.eventId = id;
    workflowRememberEvent(id);
    returnPageState.event = response.data;
    returnPageUpsertEventSummary(response.data);
    renderReturnPage();
  } catch (error) {
    showNotification('error', `Failed to load event: ${error.message}`);
    returnPageUpdatePickerOptions();
  }
}

async function returnPageRefreshSelected(options = {}) {
  const id = Number(returnPageState.eventId);
  if (!id) return;
  const snapshot = returnPageCaptureViewState();
  if (options.focusId) snapshot.focusId = options.focusId;
  const version = ++returnPageState.requestVersion;
  const response = await apiCall(`/api/events/${id}`);
  if (version !== returnPageState.requestVersion || id !== Number(returnPageState.eventId)) return;
  returnPageState.event = response.data;
  returnPageUpsertEventSummary(response.data);
  updateOverdueCounter(countOverdueEvents(returnPageState.events));
  renderReturnPage({ snapshot });
}

function returnPageHandleRealtimeEvent(event) {
  if (!event?.id) return;
  returnPageUpsertEventSummary(event);
  if (!document.getElementById('return-section')?.classList.contains('active')) return;
  if (Number(event.id) === Number(returnPageState.eventId)) {
    const snapshot = returnPageCaptureViewState();
    returnPageState.event = event;
    renderReturnPage({ snapshot });
  } else {
    returnPageUpdatePickerOptions();
  }
}

function returnPageSearchChanged(value) {
  returnPageState.search = String(value || '');
  returnPageRenderFilteredAssets({ resetScroll: true });
}

function returnPageToggleOutstanding(checked) {
  returnPageState.outstandingOnly = !!checked;
  const chipAssets = returnPageChipAssets();
  if (
    returnPageState.department !== 'ALL' &&
    !chipAssets.some(asset => asset.department === returnPageState.department)
  ) {
    returnPageState.department = 'ALL';
  }
  const chips = document.getElementById('returnDepartmentChips');
  if (chips) chips.innerHTML = returnPageDepartmentChipsHtml(chipAssets);
  returnPageRenderFilteredAssets({ resetScroll: true });
}

function returnPageSetDepartment(encodedDepartment) {
  returnPageState.department = encodedDepartment === 'ALL'
    ? 'ALL'
    : normalizeDepartmentCode(returnPageDecode(encodedDepartment));
  returnPageRenderFilteredAssets({ resetScroll: true });
}

async function returnPageRunAssetAction(action, encodedAssetId, button) {
  const assetId = returnPageDecode(encodedAssetId);
  const eventId = Number(returnPageState.eventId);
  const key = `${action}:${assetId}`;
  if (!eventId || !assetId || returnPageState.pendingActions.has(key)) return;
  returnPageState.pendingActions.add(key);
  if (button) {
    button.disabled = true;
    button.textContent = action === 'unreturn' ? 'Restoring…' : 'Returning…';
  }

  try {
    const path = action === 'unreturn'
      ? `/api/events/${eventId}/unreturn`
      : `/api/events/${eventId}/return`;
    await apiCall(path, 'POST', { assetId });
    returnPageState.pendingActions.delete(key);
    await returnPageRefreshSelected();
    playWorkflowTone('success');
    showNotification('success', action === 'unreturn'
      ? `${customAssetLabelFromId(assetId)} restored to the event`
      : `${customAssetLabelFromId(assetId)} returned successfully`);
  } catch (error) {
    returnPageState.pendingActions.delete(key);
    playWorkflowTone('error');
    showNotification('error', `${action === 'unreturn' ? 'Undo return' : 'Return'} failed: ${error.message}`);
    try {
      await returnPageRefreshSelected();
    } catch (refreshError) {
      console.warn('Return workspace reconciliation failed:', refreshError);
    }
  } finally {
    returnPageState.pendingActions.delete(key);
    if (button?.isConnected) button.disabled = false;
  }
}

function returnPageReturnAsset(encodedAssetId, button) {
  return returnPageRunAssetAction('return', encodedAssetId, button);
}

function returnPageUnreturnAsset(encodedAssetId, button) {
  return returnPageRunAssetAction('unreturn', encodedAssetId, button);
}

async function returnPageChangePreparedQuantity(action, encodedAssetId, quantity, button) {
  const assetId = returnPageDecode(encodedAssetId);
  const asset = returnPageAssets().find(row => row.id === assetId && row.isPreparedModelQuantity);
  const eventId = Number(returnPageState.eventId);
  const safeQuantity = Math.max(0, Number.parseInt(quantity, 10) || 0);
  const key = `prepared-model:${assetId}`;
  if (!eventId || !asset || safeQuantity <= 0 || returnPageState.pendingActions.has(key)) return;

  returnPageState.pendingActions.add(key);
  if (button) button.disabled = true;
  try {
    const path = action === 'unreturn'
      ? `/api/events/${eventId}/unreturn-prepared-quantity`
      : `/api/events/${eventId}/return-prepared-quantity`;
    const response = await apiCall(path, 'POST', {
      department: asset.department,
      brand: asset.brand,
      model: asset.model,
      description: asset.description,
      quantity: safeQuantity,
      subprojectId: eventActiveSubproject(returnPageState, returnPageState.event)?.id || '',
    });
    await returnPageRefreshSelected();
    playWorkflowTone('success');
    showNotification('success', response.message || (
      action === 'unreturn' ? 'Returned quantity restored' : 'Prepared quantity returned'
    ));
  } catch (error) {
    playWorkflowTone('error');
    showNotification('error', `${action === 'unreturn' ? 'Unreturn' : 'Return'} failed: ${error.message}`);
    try {
      await returnPageRefreshSelected();
    } catch (refreshError) {
      console.warn('Return workspace reconciliation failed:', refreshError);
    }
  } finally {
    returnPageState.pendingActions.delete(key);
    if (button?.isConnected) button.disabled = false;
  }
}

async function returnPagePromptPreparedQuantity(action, encodedAssetId, button) {
  const assetId = returnPageDecode(encodedAssetId);
  const asset = returnPageAssets().find(row => row.id === assetId && row.isPreparedModelQuantity);
  if (!asset) return;
  const max = action === 'unreturn'
    ? Math.max(0, Number(asset.returnedPreparedQuantity || 0))
    : Math.max(0, Number(asset.outstandingQuantity || 0));
  if (max <= 0) return;
  button?.closest('details')?.removeAttribute('open');
  const quantity = await prepareNewPromptQuantity({
    title: action === 'unreturn' ? 'Unreturn Qty' : 'Return Qty',
    message: `How many ${returnPageAssetTitle(asset)} unit(s) would you like to ${action === 'unreturn' ? 'unreturn' : 'return'}?`,
    confirmText: action === 'unreturn' ? 'Unreturn' : 'Return',
    max,
    defaultValue: max,
    inputLabel: action === 'unreturn' ? 'Quantity to restore' : 'Quantity returned',
  });
  if (quantity > 0) {
    await returnPageChangePreparedQuantity(action, encodedAssetId, quantity, button);
  }
}

async function returnPageReturnDepartment(encodedDepartment, button) {
  const eventId = Number(returnPageState.eventId);
  const department = normalizeDepartmentCode(returnPageDecode(encodedDepartment));
  const key = `department:${department}`;
  if (!eventId || returnPageState.pendingActions.has(key)) return;
  returnPageState.pendingActions.add(key);
  if (button) {
    button.disabled = true;
    button.textContent = 'Returning…';
  }
  try {
    if (eventSubprojects(returnPageState.event).length > 1) {
      const targets = returnPageAssets().filter(asset => (
        asset.department === department && !asset.isReturned
      ));
      for (const asset of targets) {
        if (asset.isPreparedModelQuantity) {
          await apiCall(`/api/events/${eventId}/return-prepared-quantity`, 'POST', {
            department: asset.department,
            brand: asset.brand,
            model: asset.model,
            description: asset.description,
            quantity: asset.outstandingQuantity,
            subprojectId: eventActiveSubproject(returnPageState, returnPageState.event)?.id || '',
          });
        } else {
          await apiCall(`/api/events/${eventId}/return`, 'POST', { assetId: asset.id });
        }
      }
      await returnPageRefreshSelected();
      showNotification('success', `${targets.length} item(s) returned for ${department}`);
      return;
    }
    const response = await apiCall(
      `/api/events/${eventId}/return-department`,
      'POST',
      { department }
    );
    const returned = response.returned || response.data?.returned || [];
    await returnPageRefreshSelected();
    showNotification('success', `${returned.length} item(s) returned for ${department}`);
  } catch (error) {
    showNotification('error', `Failed to return ${department}: ${error.message}`);
    try {
      await returnPageRefreshSelected();
    } catch (refreshError) {
      console.warn('Return workspace reconciliation failed:', refreshError);
    }
  } finally {
    returnPageState.pendingActions.delete(key);
    if (button?.isConnected) button.disabled = false;
  }
}

async function returnPageManualReturn() {
  const eventId = Number(returnPageState.eventId);
  const input = document.getElementById('returnQuickAssetInput');
  const submit = document.getElementById('returnQuickSubmit');
  let assetId = normalizeScannedIdentifier(input?.value || '');
  const scannedValue = assetId;
  if (!eventId) {
    showNotification('warning', 'Select an event first');
    return;
  }
  if (!assetId) {
    showNotification('warning', 'Enter an asset ID or serial number');
    input?.focus();
    return;
  }

  try {
    const inventoryAssets = await ensureAssetsLoaded();
    assetId = getAssetIdFromIdentifier(assetId, inventoryAssets);
  } catch (error) {
    console.warn('Could not resolve scanned return identifier locally:', error);
  }

  if (
    eventSubprojects(returnPageState.event).length > 1 &&
    !returnPageAssets().some(asset => String(asset.id) === String(assetId))
  ) {
    showNotification('warning', 'This asset belongs to a different sub-project');
    input?.focus();
    return;
  }

  const key = `return:${assetId}`;
  if (returnPageState.pendingActions.has(key)) return;
  returnPageState.pendingActions.add(key);
  if (submit) {
    submit.disabled = true;
    submit.textContent = 'Returning…';
  }

  try {
    await apiCall(`/api/events/${eventId}/return`, 'POST', { assetId });
    const queuedValue = normalizeScannedIdentifier(input?.value || '') !== normalizeScannedIdentifier(scannedValue)
      ? String(input?.value || '')
      : '';
    clearWorkflowScanInput(input, scannedValue);
    await returnPageRefreshSelected({ focusId: 'returnQuickAssetInput' });
    const refreshedInput = document.getElementById('returnQuickAssetInput');
    if (queuedValue && refreshedInput && !refreshedInput.value) refreshedInput.value = queuedValue;
    playWorkflowTone('success');
    showNotification('success', `${customAssetLabelFromId(assetId)} returned successfully`);
  } catch (error) {
    playWorkflowTone('error');
    showNotification('error', `Return failed: ${error.message}`);
    if (input) {
      input.focus();
    }
    try {
      await returnPageRefreshSelected({ focusId: 'returnQuickAssetInput' });
    } catch (refreshError) {
      console.warn('Return workspace reconciliation failed:', refreshError);
    }
  } finally {
    returnPageState.pendingActions.delete(key);
    const currentInput = document.getElementById('returnQuickAssetInput');
    if (currentInput && getEventReturnableCount(returnPageState.event) > 0) {
      currentInput.focus({ preventScroll: true });
    }
  }
}

async function returnPageExit() {
  const eventId = Number(returnPageState.eventId);
  const metrics = returnPageMetrics();
  if (!eventId || metrics.total <= 0 || metrics.remaining > 0) {
    showSection('events');
    return;
  }

  try {
    await apiCall(`/api/events/${eventId}/close-return`, 'POST', {});
    showNotification('success', `Event ${eventId} closed`);
    returnPageState.eventId = null;
    returnPageState.event = null;
    returnPageState.loaded = false;
    await loadReturnWorkspace({ preservePosition: false, keepSelection: false });
  } catch (error) {
    showNotification('error', `Failed to close event: ${error.message}`);
  }
}


async function loadEventAssetsForReturn() {
    const eventId = returnPageState.eventId;

    if (!eventId) {
        document.getElementById('event-summary').style.display = 'none';
        document.getElementById('assets-return-section').style.display = 'none';
        return;
    }

    try {
        const response = await apiCall(`/api/events/${eventId}`);
        const event = response.data;

        const returnAssets = [];
        if (event.assetsByDepartment) {
            Object.entries(event.assetsByDepartment).forEach(([dept, deptAssets]) => {
                (deptAssets || []).forEach(asset => {
                    if (!asset || !asset.id || String(asset.id).startsWith('[MODEL]')) return;
                    returnAssets.push({ ...asset, department: asset.department || dept });
                });
            });
        }

        const totalReturnedIncludingCustom = returnAssets
            .filter(asset => asset.status === 'returned')
            .reduce((sum, asset) => sum + Number(asset.quantity || 1), 0);
        const remainingAssets = returnAssets.filter(asset => isAssetReturnableFromEventDetail(asset, event));
        const remaining = remainingAssets.reduce((sum, asset) => sum + Number(asset.quantity || 1), 0);
        const totalAssetsIncludingCustom = Math.max(Number(event.returnableTotalCount || 0), totalReturnedIncludingCustom + remaining);

        const summaryDiv = document.getElementById('event-summary');
        summaryDiv.style.display = 'block';
        summaryDiv.innerHTML = `
            <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 15px; text-align: center;">
                <div>
                    <div style="font-size: 24px; font-weight: bold; color: #007bff;">${totalAssetsIncludingCustom}</div>
                    <div style="color: #6c757d; font-size: 12px;">Total Assets</div>
                </div>
                <div>
                    <div style="font-size: 24px; font-weight: bold; color: #28a745;">${totalReturnedIncludingCustom}</div>
                    <div style="color: #6c757d; font-size: 12px;">Returned</div>
                </div>
                <div>
                    <div style="font-size: 24px; font-weight: bold; color: #ffc107;">${remaining}</div>
                    <div style="color: #6c757d; font-size: 12px;">Remaining</div>
                </div>
            </div>
        `;

        const assetsSection = document.getElementById('assets-return-section');
        assetsSection.style.display = 'block';

        const byDept = {};
        remainingAssets.forEach(asset => {
            const custom = parseCustomAsset(asset.id, asset);
            const dept = normalizeDepartmentCode(custom?.department || asset.department || 'UN');
            if (!byDept[dept]) byDept[dept] = [];
            byDept[dept].push({ ...asset, parsedCustom: custom });
        });

        const deptCodes = Object.keys(byDept).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

        let assetsContent = '';

        if (deptCodes.length > 0) {
            const quickRows = deptCodes.map(dept => {
                const items = byDept[dept] || [];
                const unreturnedQty = items.reduce((sum, a) => sum + Number(a.quantity || a.parsedCustom?.quantity || 1), 0);
                return `
                    <div style="display:flex; justify-content:space-between; align-items:center; padding:8px 12px; border:1px solid #e9ecef; border-radius:8px; margin-bottom:8px; background:white;">
                        <div style="font-weight:600;">${departmentBadgeHtml(dept, true)}</div>
                        <div style="display:flex; align-items:center; gap:10px;">
                            <span style="font-size:12px; color:#6c757d;">${unreturnedQty} to return</span>
                            ${isAdminUser() ? `<button class="btn btn-success btn-sm" onclick="returnAllForDepartment(${eventId}, '${escapeJs(dept)}')">Return all</button>` : ''}
                        </div>
                    </div>
                `;
            }).join('');

            assetsContent += `
                <div style="margin-bottom:16px; padding:12px; background:#f8f9fa; border:1px solid #e9ecef; border-radius:10px;">
                    <div style="font-weight:600; margin-bottom:8px; color:#495057;">Department quick actions</div>
                    ${quickRows}
                </div>
            `;
        }

        deptCodes.forEach(dept => {
            const items = (byDept[dept] || []).sort((a, b) =>
                compareByDisplayName(assetDisplaySortName(a), assetDisplaySortName(b))
            );
            const totalQty = items.reduce((sum, a) => sum + Number(a.quantity || a.parsedCustom?.quantity || 1), 0);

            assetsContent += `
                <div class="dept-section" style="margin-bottom: 20px; border: 1px solid #e9ecef; border-radius: 8px; overflow:hidden;">
                    <div style="display:flex; justify-content:space-between; align-items:center; padding:12px 15px; background:#f1f3f4; border-bottom:1px solid #e9ecef;">
                        <h5 style="margin:0; color:#495057; font-size:14px;">${departmentBadgeHtml(dept, true)} Department</h5>
                        <div style="font-size:12px; font-weight:600; color:#ffc107;">${totalQty} to return</div>
                    </div>
                    <div style="padding:10px; background:white;">
            `;

            items.forEach((asset, index) => {
                const custom = asset.parsedCustom;
                const isBulk = asset.isBulk || String(asset.id || '').startsWith('[BULK]');
                const encodedAssetId = encodeURIComponent(asset.id);
                const rowBg = index % 2 === 0 ? '#f8f9fa' : 'white';
                let title = '';
                let subtitle = '';
                let badge = '';

                if (custom) {
                    title = customAssetDisplayName(custom);
                    badge = customAssetTypeBadge(custom);
                    subtitle = customAssetDetailText(custom);
                } else if (isBulk) {
                    title = `${asset.brand || ''} ${asset.model || ''}`.trim() || 'Bulk Item';
                    subtitle = `${asset.description || ''}${asset.description ? ' • ' : ''}Bulk quantity item • Qty: ${asset.quantity || 1}`;
                } else {
                    title = asset.id || 'Asset';
                    const desc = `${asset.brand || ''} ${asset.model || ''}${asset.description ? ' - ' + asset.description : ''}`.trim();
                    subtitle = [desc, asset.serial ? `SN: ${asset.serial}` : '', asset.location ? `Location: ${asset.location}` : ''].filter(Boolean).join(' • ');
                }

                assetsContent += `
                    <div class="return-asset-item" style="display:flex; justify-content:space-between; align-items:center; gap:12px; padding:12px; background:${rowBg}; border-radius:6px; margin-bottom:8px; border:1px solid #eef0f2;">
                        <div style="min-width:0; flex:1;">
                            <div style="font-weight:500; font-size:14px; color:#333; overflow-wrap:anywhere;">${escapeHtml(title)} ${badge}</div>
                            ${subtitle ? `<div style="color:#666; font-size:11px; margin-top:2px; overflow-wrap:anywhere;">${escapeHtml(subtitle)}</div>` : ''}
                        </div>
                        <div style="display:flex; align-items:center; gap:8px; flex-shrink:0;">
                            <button class="btn btn-warning return-asset-btn" data-return-event-id="${eventId}" data-return-asset-id="${escapeHtmlAttr(encodedAssetId)}" style="padding:6px 12px; font-size:12px;" onclick="returnSpecificAssetNew(${eventId}, '${escapeJs(encodedAssetId)}', this)">Return</button>
                        </div>
                    </div>
                `;
            });

            assetsContent += '</div></div>';
        });

        if (!assetsContent) {
            assetsContent = '<p style="text-align: center; color: #666; padding: 40px;">No assets available for return.</p>';
        }

        document.getElementById('return-assets-list').innerHTML = assetsContent;

    } catch (error) {
        showNotification('error', 'Failed to load event assets');
        console.error('Error loading event assets for return:', error);
    }
}


function decodeReturnAssetArgument(value) {
    try {
        return decodeURIComponent(String(value || ''));
    } catch (error) {
        return String(value || '');
    }
}

function findReturnAssetButton(eventId, assetId) {
    const encodedAssetId = encodeURIComponent(String(assetId || ''));
    return Array.from(document.querySelectorAll('.return-asset-btn')).find(button =>
        button.dataset.returnEventId === String(eventId) &&
        button.dataset.returnAssetId === encodedAssetId
    ) || null;
}

async function returnSpecificAssetNew(eventId, assetId, buttonElement = null) {
    const decodedAssetId = decodeReturnAssetArgument(assetId);

    // Prevent multiple clicks
    buttonElement = buttonElement || findReturnAssetButton(eventId, decodedAssetId);
    if (buttonElement && buttonElement.disabled) {
        return;
    }

    try {
        // Disable the button immediately
        if (buttonElement) {
            buttonElement.disabled = true;
            buttonElement.style.opacity = '0.5';
            buttonElement.textContent = 'Returning...';
        }

        await apiCall(`/api/events/${eventId}/return`, 'POST', { assetId: decodedAssetId });
        showNotification('success', `${customAssetLabelFromId(decodedAssetId)} returned successfully`);

        // Remove the asset from the UI with animation
        const parentItem = buttonElement ? buttonElement.closest('.return-asset-item') : null;
        if (parentItem) {
            parentItem.style.transition = 'opacity 0.3s ease';
            parentItem.style.opacity = '0.3';
            parentItem.style.pointerEvents = 'none';

            setTimeout(() => {
                if (parentItem.parentNode) {
                    parentItem.parentNode.removeChild(parentItem);
                }
                // Refresh the event summary after removal
                setTimeout(() => {
                    loadEventAssetsForReturn();
                }, 100);
            }, 300);
        } else {
            // Fallback refresh if we can't find the specific element
            setTimeout(() => {
                loadEventAssetsForReturn();
            }, 500);
        }

        // Update overdue counter
        await loadStatsCards();

    } catch (error) {
        showNotification('error', `Failed to return asset: ${error.message}`);
        console.error('Error returning asset:', error);

        // Re-enable button on error
        if (buttonElement) {
            buttonElement.disabled = false;
            buttonElement.style.opacity = '1';
            buttonElement.textContent = 'Return';
        }
    }
}

async function returnAllForDepartment(eventId, department) {
  if (!isAdminUser()) {
      showNotification('error', 'Admin privileges required to use Return all');
      return;
  }

  try {
      // Best-effort disable of the clicked button
      const btn = document.querySelector(`[onclick*="returnAllForDepartment(${eventId}, '${department.replace("'", "\\'")}')"]`);
      if (btn) {
          btn.disabled = true;
          btn.textContent = 'Returning...';
          btn.style.opacity = '0.6';
      }

      const res = await apiCall(`/api/events/${eventId}/return-department`, 'POST', { department });

      // Prefer explicit count, then top-level returned[], then data.returned[]
      const returnedList =
        Array.isArray(res?.returned) ? res.returned :
        Array.isArray(res?.data?.returned) ? res.data.returned : [];

      const count =
        Number.isFinite(res?.count) ? res.count :
        Number.isFinite(res?.data?.count) ? res.data.count :
        returnedList.length;

      // Use a consistent success message
      showNotification('success', `${count} item(s) returned for ${department}`);


      // Refresh views
      loadEventAssetsForReturn();
      if (document.getElementById('return-section').classList.contains('active')) {
          loadReturnEvents();
      }
      if (document.getElementById('dashboard-section').classList.contains('active')) {
          loadDashboard();
      }
      if (document.getElementById('events-section').classList.contains('active')) {
          loadAllEvents();
      }
  } catch (error) {
      console.error('Error returning department assets:', error);
      showNotification('error', `Failed to return all for ${department}`);
  }
}

async function returnManualAssetNew() {
    const assetInput = document.getElementById('returnQuickAssetInput');
    const eventId = returnPageState.eventId;
    let assetId = normalizeScannedIdentifier(assetInput.value);

    if (!eventId) {
        showNotification('warning', 'Please select an event first');
        return;
    }

    if (!assetId) {
        showNotification('warning', 'Please enter an asset ID');
        return;
    }

    try {
      const inventoryAssets = await ensureAssetsLoaded();
      assetId = getAssetIdFromIdentifier(assetId, inventoryAssets);
      assetInput.value = assetId;
    } catch (error) {
      console.warn('Could not resolve scanned return identifier locally:', error);
    }

    try {
        await apiCall(`/api/events/${eventId}/return`, 'POST', { assetId });
        showNotification('success', `${assetId} returned successfully`);

        // Clear input and focus back on it
        assetInput.value = '';
        assetInput.focus();

        // Refresh the event assets display
        loadEventAssetsForReturn();

        // Update overdue counter
        await loadStatsCards();

    } catch (error) {
        showNotification('error', `Failed to return asset: ${error.message}`);
    }
}

let transferOptionsCache = null;
let transferCandidateCache = [];
let transferPageState = {
  sourceEventId: null,
  targetEventId: null,
  targetSubprojectId: ''
};

async function loadTransferHistory() {
  const container = document.getElementById("transfer-history");
  if (!container) return;

  container.innerHTML = '<div class="loading">Loading transfer options...</div>';

  try {
    let offset = 0;
    let loadedCandidates = false;
    let rendered = false;
    transferOptionsCache = { events: [], sourceEvents: [], targetEvents: [] };

    while (true) {
      const response = await apiCall(
        `/api/transfers/options?limit=${EVENT_OPTIONS_PAGE_SIZE}&offset=${offset}`
      );
      const page = response.data || {};
      ['events', 'sourceEvents', 'targetEvents'].forEach(key => {
        transferOptionsCache[key] = mergeEventsById(
          transferOptionsCache[key],
          page[key] || []
        );
      });

      const selectableEvents = transferSelectableEvents();
      updateOverdueCounter(selectableEvents.filter(event => event.state === 'Overdue').length);
      if (!rendered) {
        renderTransferWorkspace();
        rendered = true;
      }
      populateTransferDropdowns(transferOptionsCache);

      const sourceSelect = document.getElementById('transferSourceSelect');
      const targetSelect = document.getElementById('transferTargetSelect');
      if (
        !loadedCandidates &&
        sourceSelect?.value &&
        targetSelect?.value
      ) {
        loadedCandidates = true;
        await loadTransferCandidates();
      }

      if (!response.meta?.hasMore || !page.events?.length) break;
      offset = Number(response.meta.nextOffset || 0);
      await new Promise(resolve => requestAnimationFrame(resolve));
    }

    const availableIds = new Set(
      transferSelectableEvents().map(event => String(event.id || ''))
    );
    let selectionChanged = false;
    if (transferPageState.sourceEventId && !availableIds.has(String(transferPageState.sourceEventId))) {
      transferPageState.sourceEventId = null;
      selectionChanged = true;
    }
    if (transferPageState.targetEventId && !availableIds.has(String(transferPageState.targetEventId))) {
      transferPageState.targetEventId = null;
      transferPageState.targetSubprojectId = '';
      selectionChanged = true;
    }
    if (selectionChanged) {
      renderTransferWorkspace();
      populateTransferDropdowns(transferOptionsCache);
    }
  } catch (error) {
    container.innerHTML = `
      <div style="padding:30px;text-align:center;color:#a00;">
        Failed to load transfer options: ${escapeHtml(error.message || String(error))}
        <br><br>
        <button class="btn btn-primary" onclick="loadTransferHistory()">Retry</button>
      </div>
    `;
  }
}










async function openManualTransferModal() {
  if (!transferOptionsCache) {
    const response = await apiCall('/api/transfers/options');
    transferOptionsCache = response.data || { sourceEvents: [], targetEvents: [] };
  }
  populateTransferDropdowns(transferOptionsCache);
  openModal('transferModal');
}

