function formatMaintenanceCost(value) {
  const raw = String(value ?? '').trim();
  if (!raw) return '';

  const cleaned = raw.replace(/,/g, '').replace(/^\$/, '').trim();
  if (!cleaned) return '';

  const amount = Number(cleaned);
  if (!Number.isFinite(amount)) return raw;

  return amount.toFixed(2);
}

function maintenanceCostDisplayHtml(value, emptyHtml = '-') {
  const cost = formatMaintenanceCost(value);
  return cost ? `$${escapeHtml(cost)}` : emptyHtml;
}

function normalizeMaintenanceMedia(media) {
  if (!Array.isArray(media)) return [];
  return media
    .filter(item => item && typeof item === 'object')
    .map(item => ({
      id: String(item.id || item.mediaId || ''),
      name: String(item.name || item.filename || item.originalName || 'Media'),
      kind: String(item.kind || item.type || '').toLowerCase() === 'video' ? 'video' : 'image',
      mimeType: String(item.mimeType || item.contentType || ''),
      size: Number(item.size || 0),
      url: String(item.url || (item.id ? `/api/maintenance-media/${encodeURIComponent(item.id)}` : ''))
    }))
    .filter(item => item.id && item.url);
}

function maintenanceMediaLinksHtml(media, emptyHtml = '<span style="color:#999;">—</span>', options = {}) {
  const items = normalizeMaintenanceMedia(media);
  if (!items.length) return emptyHtml;

  let imageCount = 0;
  let videoCount = 0;
  const allowDelete = Boolean(options.allowDelete && isAdminUser());
  const assetId = String(options.assetId || '');
  const logIndex = Number.isInteger(options.logIndex) ? options.logIndex : -1;

  return `
    <div style="display:flex;flex-wrap:wrap;gap:6px;">
      ${items.map(item => {
        const label = item.kind === 'video'
          ? `Video ${++videoCount}`
          : `Photo ${++imageCount}`;
        const title = item.name || label;
        return `
          <span data-maintenance-media-item data-maintenance-media-id="${escapeHtmlAttr(item.id)}" style="display:inline-flex;align-items:center;gap:3px;">
            <a
              class="maintenance-media-link"
            href="${escapeHtmlAttr(item.url)}"
            target="_blank"
            rel="noopener"
            title="${escapeHtmlAttr(title)}"
            onclick="event.stopPropagation()"
          >${escapeHtml(label)}</a>
            ${allowDelete ? `
              <button
                type="button"
                class="maintenance-media-delete-btn"
                title="Permanently remove ${escapeHtmlAttr(title)}"
                aria-label="Permanently remove ${escapeHtmlAttr(title)}"
                data-maintenance-media-delete
                data-media-id="${escapeHtmlAttr(item.id)}"
                data-asset-id="${escapeHtmlAttr(assetId)}"
                data-log-index="${logIndex}"
                style="border:0;background:transparent;color:#dc3545;cursor:pointer;font-size:16px;line-height:1;padding:2px 4px;"
              >&times;</button>
            ` : ''}
          </span>
        `;
      }).join('')}
    </div>
  `;
}

function bindMaintenanceMediaDeleteButtons(root = document) {
  root.querySelectorAll('[data-maintenance-media-delete]:not([data-delete-bound="true"])').forEach(button => {
    button.dataset.deleteBound = 'true';
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      deleteMaintenanceMedia(
        button.dataset.mediaId || '',
        button.dataset.assetId || '',
        Number(button.dataset.logIndex ?? -1),
        button
      );
    });
  });
}

const maintenancePendingMediaSelections = new WeakMap();

function maintenancePendingMediaFiles(input) {
  if (!input) return [];
  return maintenancePendingMediaSelections.has(input)
    ? maintenancePendingMediaSelections.get(input)
    : Array.from(input.files || []);
}

function setMaintenancePendingMediaFiles(input, files) {
  const selected = Array.from(files || []).filter(Boolean);
  maintenancePendingMediaSelections.set(input, selected);
  try {
    if (typeof DataTransfer !== 'undefined') {
      const transfer = new DataTransfer();
      selected.forEach(file => transfer.items.add(file));
      input.files = transfer.files;
    }
  } catch (error) {
    // Some mobile browsers expose a read-only FileList. Submission uses the
    // accumulated selection above, so the files are still retained.
  }
  return selected;
}

function updateMaintenanceMediaSelection(inputId, listId) {
  const input = document.getElementById(inputId);
  const list = document.getElementById(listId);
  if (!input || !list) return;

  const files = maintenancePendingMediaFiles(input);
  list.innerHTML = files.map((file, index) => `
    <span class="maintenance-media-pill" title="${escapeHtmlAttr(file.name)}">
      <span class="maintenance-media-pill-name">${escapeHtml(file.name)}</span>
      <button type="button" class="maintenance-media-pill-remove"
              title="Remove ${escapeHtmlAttr(file.name)}" aria-label="Remove ${escapeHtmlAttr(file.name)}"
              onclick="removeMaintenancePendingMedia(event,'${escapeHtmlAttr(inputId)}','${escapeHtmlAttr(listId)}',${index})">&times;</button>
    </span>
  `).join('');
  const dropzone = document.querySelector(`[data-maintenance-drop-input="${inputId}"]`) || document.getElementById('maintenanceMediaDropzone');
  if (dropzone) dropzone.classList.toggle('has-files', files.length > 0);
}

function appendMaintenanceMediaSelection(inputId, listId, addedFiles = null) {
  const input = document.getElementById(inputId);
  if (!input) return;
  const existing = maintenancePendingMediaSelections.get(input) || [];
  const selected = addedFiles === null
    ? Array.from(input.files || [])
    : Array.from(addedFiles || []);
  setMaintenancePendingMediaFiles(input, [...existing, ...selected]);
  updateMaintenanceMediaSelection(inputId, listId);
}

function resetMaintenanceMediaSelection(inputId, listId) {
  const input = document.getElementById(inputId);
  if (!input) return;
  input.value = '';
  setMaintenancePendingMediaFiles(input, []);
  updateMaintenanceMediaSelection(inputId, listId);
}

function removeMaintenancePendingMedia(event, inputId, listId, fileIndex) {
  event?.preventDefault();
  event?.stopPropagation();
  const input = document.getElementById(inputId);
  if (!input) return;
  const files = maintenancePendingMediaFiles(input);
  if (fileIndex < 0 || fileIndex >= files.length) return;
  setMaintenancePendingMediaFiles(
    input,
    files.filter((_file, index) => index !== fileIndex)
  );
  updateMaintenanceMediaSelection(inputId, listId);
}

function setupMaintenanceMediaDropzone(inputId, listId, dropzoneId) {
  const input = document.getElementById(inputId);
  const dropzone = document.getElementById(dropzoneId);
  if (!input || !dropzone || dropzone.dataset.dropBound === 'true') return;
  dropzone.dataset.dropBound = 'true';
  dropzone.dataset.maintenanceDropInput = inputId;

  ['dragenter', 'dragover'].forEach(type => dropzone.addEventListener(type, event => {
    event.preventDefault();
    event.stopPropagation();
    dropzone.classList.add('drag-active');
    if (event.dataTransfer) event.dataTransfer.dropEffect = 'copy';
  }));
  ['dragleave', 'dragend'].forEach(type => dropzone.addEventListener(type, event => {
    event.preventDefault();
    event.stopPropagation();
    if (type === 'dragend' || !dropzone.contains(event.relatedTarget)) dropzone.classList.remove('drag-active');
  }));
  dropzone.addEventListener('drop', event => {
    event.preventDefault();
    event.stopPropagation();
    dropzone.classList.remove('drag-active');
    const dropped = Array.from(event.dataTransfer?.files || []).filter(file => {
      const name = String(file.name || '').toLowerCase();
      return String(file.type || '').startsWith('image/') || String(file.type || '').startsWith('video/') || /\.(jpe?g|png|mp4|mov)$/.test(name);
    });
    if (!dropped.length) {
      showNotification('warning', 'Please choose photo or video files');
      return;
    }
    appendMaintenanceMediaSelection(inputId, listId, dropped);
  });
}

function maintenancePayloadToRequestData(payload, mediaInputId) {
  const input = document.getElementById(mediaInputId);
  const files = maintenancePendingMediaFiles(input);
  if (!files.length) return payload;

  const formData = new FormData();
  Object.entries(payload).forEach(([key, value]) => {
    if (value !== null && value !== undefined) {
      formData.append(key, value);
    }
  });
  files.forEach(file => formData.append('media', file));
  return formData;
}

function normalizeMaintenanceLogRecord(log) {
  if (log && typeof log === 'object' && !Array.isArray(log)) {
    return {
      id: String(log.id || log.logId || ''),
      date: String(log.date || ''),
      createdAt: String(log.createdAt || log.created_at || ''),
      user: String(log.user || ''),
      userDisplayName: String(log.userDisplayName || log.user || ''),
      description: String(log.description || ''),
      type: normalizeMaintenanceLogType(log.type || log.logType || log.maintenanceType),
      cost: formatMaintenanceCost(log.cost),
      changes: Array.isArray(log.changes)
        ? log.changes.map(normalizeMaintenanceChange).filter(Boolean)
        : [],
      source: log.source && typeof log.source === 'object' ? { ...log.source } : {},
      media: normalizeMaintenanceMedia(log.media || log.attachments)
    };
  }

  const parts = String(log || '').split('\t');
  const parsed = parts.length >= 3
    ? { date: parts[0] || '', user: parts[1] || '', description: parts.slice(2).join('\t') || '' }
    : { date: '', user: '', description: String(log || '') };
  const legacy = splitLegacyMaintenanceStatus(parsed.description);
  return { ...parsed, id: '', createdAt: '', description: legacy.description, type: DEFAULT_MAINTENANCE_LOG_TYPE, cost: '', changes: legacy.changes, source: {}, media: [] };
}

function getMaintenanceLogRecords(asset) {
  const source = Array.isArray(asset?.maintenanceLogRecords)
    ? asset.maintenanceLogRecords
    : (Array.isArray(asset?.maintenanceLogs) ? asset.maintenanceLogs : []);
  return source.map(normalizeMaintenanceLogRecord);
}

async function loadMaintenanceUserOptions(force = false) {
  if (!force && maintenanceUserOptionsCache.length) {
    return maintenanceUserOptionsCache;
  }
  try {
    const response = await apiCall('/api/maintenance/users');
    maintenanceUserOptionsCache = Array.isArray(response?.data)
      ? response.data.filter(option => option?.username)
      : [];
  } catch (error) {
    console.error('Failed to load maintenance users:', error);
    const username = String(currentUser?.username || '').trim();
    maintenanceUserOptionsCache = username
      ? [{ username, name: String(currentUser?.name || username).trim() || username }]
      : [];
  }
  return maintenanceUserOptionsCache;
}

function maintenanceUserOptionsHtml(options) {
  return options.map(option => {
    const username = String(option.username || '').trim();
    const name = String(option.name || username).trim() || username;
    const label = name.toLowerCase() === username.toLowerCase()
      ? name
      : `${name} (${username})`;
    return `<option value="${escapeHtmlAttr(username)}">${escapeHtml(label)}</option>`;
  }).join('');
}

async function populateMaintenanceUserSelect(selectId, selectedUsername = '', force = false) {
  const select = document.getElementById(selectId);
  if (!select) return;
  select.disabled = true;
  select.innerHTML = '<option value="">Loading users...</option>';

  const options = await loadMaintenanceUserOptions(force);
  if (!document.getElementById(selectId)) return;
  select.innerHTML = maintenanceUserOptionsHtml(options)
    || '<option value="">No active users available</option>';
  const preferred = String(selectedUsername || currentUser?.username || '').trim();
  const selected = options.some(option => option.username === preferred)
    ? preferred
    : String(options[0]?.username || '');
  select.value = selected;
  select.disabled = !options.length;
}

function maintenanceEventReferenceContext(textarea) {
  const caret = Number(textarea?.selectionStart ?? -1);
  if (!textarea || caret < 0) return null;
  const beforeCaret = textarea.value.slice(0, caret);
  const markerStart = beforeCaret.lastIndexOf('`');
  if (markerStart < 0) return null;
  const precedingMarkers = (beforeCaret.slice(0, markerStart).match(/`/g) || []).length;
  if (precedingMarkers % 2 !== 0) return null;

  const query = beforeCaret.slice(markerStart + 1);
  if (query.includes('\n') || query.length > 100) return null;
  return { markerStart, caret, query: query.trim() };
}

function maintenanceEventReferenceToken(event) {
  const eventId = String(event?.id || '').trim();
  const eventName = String(event?.name || `Event ${eventId}`)
    .replace(/`/g, "'")
    .replace(/\*\*/g, '')
    .trim();
  return '`' + eventId + ': **' + eventName + '**`';
}

function maintenanceDescriptionPlainText(description) {
  return String(description || '').replace(
    /`(\d+)\s*:\s*\*\*([^`\n]+?)\*\*`/g,
    (_match, eventId, eventName) => `${eventId}: ${String(eventName || '').trim()}`
  );
}

function maintenanceDescriptionHtml(description, options = {}) {
  const source = String(description || '');
  const interactive = options.interactive !== false;
  const pattern = /`(\d+)\s*:\s*\*\*([^`\n]+?)\*\*`/g;
  let output = '';
  let cursor = 0;
  let match;
  while ((match = pattern.exec(source)) !== null) {
    output += escapeHtml(source.slice(cursor, match.index));
    const referenceContent = `<span>${escapeHtml(match[1])}:</span> <strong>${escapeHtml(match[2].trim())}</strong>`;
    output += interactive
      ? `<button type="button" class="maintenance-event-reference" title="View event ${escapeHtmlAttr(match[1])}" aria-label="View event ${escapeHtmlAttr(match[1])}: ${escapeHtmlAttr(match[2].trim())}" onclick="viewMaintenanceReferencedEvent(event,${Number(match[1])})" onkeydown="event.stopPropagation()">${referenceContent}</button>`
      : `<span class="maintenance-event-reference is-static">${referenceContent}</span>`;
    cursor = pattern.lastIndex;
  }
  output += escapeHtml(source.slice(cursor));
  return output;
}

function viewMaintenanceReferencedEvent(clickEvent, eventId) {
  clickEvent?.preventDefault();
  clickEvent?.stopPropagation();
  const numericEventId = Number(eventId);
  if (!numericEventId) return;
  document.getElementById('eventDetailsModal')?.classList.add('maintenance-reference-overlay');
  void viewEvent(numericEventId, { updateHistory: false });
}

function hideMaintenanceEventSuggestions(state) {
  if (!state?.popup) return;
  state.popup.hidden = true;
  state.popup.innerHTML = '';
  state.events = [];
  state.activeIndex = -1;
}

function renderMaintenanceEventSuggestions(state, matchingEvents) {
  state.events = matchingEvents;
  state.activeIndex = matchingEvents.length ? 0 : -1;
  if (!matchingEvents.length) {
    state.popup.innerHTML = '<div class="maintenance-event-suggestion-empty">No matching events</div>';
    state.popup.hidden = false;
    return;
  }

  state.popup.innerHTML = matchingEvents.map((event, index) => {
    const meta = [event.startDate, event.location, event.state].filter(Boolean).join(' · ');
    return `
      <button type="button" class="maintenance-event-suggestion${index === 0 ? ' active' : ''}" data-event-index="${index}" role="option" aria-selected="${index === 0 ? 'true' : 'false'}">
        <span><b>${escapeHtml(String(event.id || ''))}:</b> <strong>${escapeHtml(event.name || `Event ${event.id || ''}`)}</strong></span>
        ${meta ? `<small>${escapeHtml(meta)}</small>` : ''}
      </button>
    `;
  }).join('');
  state.popup.hidden = false;
  state.popup.querySelectorAll('[data-event-index]').forEach(button => {
    button.addEventListener('mousedown', event => event.preventDefault());
    button.addEventListener('click', () => {
      selectMaintenanceEventReference(state, Number(button.dataset.eventIndex));
    });
  });
}

function setMaintenanceEventSuggestionActive(state, nextIndex) {
  if (!state.events.length) return;
  state.activeIndex = (nextIndex + state.events.length) % state.events.length;
  state.popup.querySelectorAll('[data-event-index]').forEach((button, index) => {
    const active = index === state.activeIndex;
    button.classList.toggle('active', active);
    button.setAttribute('aria-selected', String(active));
    if (active) button.scrollIntoView({ block: 'nearest' });
  });
}

function selectMaintenanceEventReference(state, eventIndex) {
  const selectedEvent = state.events[eventIndex];
  const context = state.context;
  if (!selectedEvent || !context) return;
  const textarea = state.textarea;
  const token = maintenanceEventReferenceToken(selectedEvent);
  textarea.value = textarea.value.slice(0, context.markerStart)
    + token
    + textarea.value.slice(context.caret);
  const nextCaret = context.markerStart + token.length;
  textarea.focus();
  textarea.setSelectionRange(nextCaret, nextCaret);
  hideMaintenanceEventSuggestions(state);
  textarea.dispatchEvent(new Event('input', { bubbles: true }));
}

async function loadMaintenanceEventSuggestions(state, context) {
  const requestId = ++state.requestId;
  const query = new URLSearchParams({
    view: 'options',
    query: context.query,
    limit: '8',
    sort: 'startDate',
    direction: 'desc'
  });
  try {
    const response = await apiCall(`/api/events?${query.toString()}`);
    if (requestId !== state.requestId || !state.textarea.isConnected) return;
    renderMaintenanceEventSuggestions(
      state,
      Array.isArray(response?.data) ? response.data : []
    );
  } catch (error) {
    if (requestId === state.requestId) hideMaintenanceEventSuggestions(state);
  }
}

function setupMaintenanceEventReferenceInput(textareaOrId) {
  const textarea = typeof textareaOrId === 'string'
    ? document.getElementById(textareaOrId)
    : textareaOrId;
  if (!textarea || textarea.dataset.eventReferencesReady === 'true') return;
  textarea.dataset.eventReferencesReady = 'true';

  const field = textarea.closest('.form-group') || textarea.parentElement;
  field?.classList.add('maintenance-event-reference-field');
  const popup = document.createElement('div');
  popup.className = 'maintenance-event-suggestions';
  popup.hidden = true;
  popup.setAttribute('role', 'listbox');
  popup.setAttribute('aria-label', 'Event suggestions');
  textarea.insertAdjacentElement('afterend', popup);

  const state = {
    textarea,
    popup,
    context: null,
    events: [],
    activeIndex: -1,
    requestId: 0,
    timer: null
  };
  const update = () => {
    const context = maintenanceEventReferenceContext(textarea);
    state.context = context;
    clearTimeout(state.timer);
    if (!context) {
      state.requestId += 1;
      hideMaintenanceEventSuggestions(state);
      return;
    }
    popup.innerHTML = '<div class="maintenance-event-suggestion-empty">Searching events...</div>';
    popup.hidden = false;
    state.timer = setTimeout(() => loadMaintenanceEventSuggestions(state, context), 140);
  };

  textarea.addEventListener('input', update);
  textarea.addEventListener('click', update);
  textarea.addEventListener('keyup', event => {
    if (!['ArrowDown', 'ArrowUp', 'Enter', 'Escape'].includes(event.key)) update();
  });
  textarea.addEventListener('keydown', event => {
    if (popup.hidden) return;
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      setMaintenanceEventSuggestionActive(state, state.activeIndex + 1);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      setMaintenanceEventSuggestionActive(state, state.activeIndex - 1);
    } else if (event.key === 'Enter' && state.activeIndex >= 0) {
      event.preventDefault();
      selectMaintenanceEventReference(state, state.activeIndex);
    } else if (event.key === 'Escape') {
      event.preventDefault();
      hideMaintenanceEventSuggestions(state);
    }
  });
  textarea.addEventListener('blur', () => {
    setTimeout(() => hideMaintenanceEventSuggestions(state), 120);
  });
}

function maintenanceLogUserLabel(log) {
  return String(log?.userDisplayName || log?.user || '').trim();
}

function isContainerMaintenanceLog(log) {
  const record = normalizeMaintenanceLogRecord(log);
  return String(record.source?.kind || '').trim().toLowerCase() === 'container';
}

function maintenanceLogOriginBadgeHtml(log) {
  const record = normalizeMaintenanceLogRecord(log);
  if (!isContainerMaintenanceLog(record)) return '';

  const containerId = String(record.source?.containerId || '').trim() || 'Container';
  return `
    <span
      style="display:inline-block;margin-top:5px;padding:3px 7px;border-radius:999px;font-size:11px;font-weight:700;white-space:nowrap;background:#e8f1ff;color:#2457a6;border:1px solid #c9dcfb;"
      title="This maintenance log was created through container ${escapeHtmlAttr(containerId)}"
    >Container: ${escapeHtml(containerId)}</span>
  `;
}

function maintenanceLogDateSortValue(dateValue) {
  const match = String(dateValue || '').trim().match(/^(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})/);
  if (!match) return Number.NEGATIVE_INFINITY;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const timestamp = Date.UTC(year, month - 1, day);
  const parsed = new Date(timestamp);
  if (
    parsed.getUTCFullYear() !== year ||
    parsed.getUTCMonth() !== month - 1 ||
    parsed.getUTCDate() !== day
  ) {
    return Number.NEGATIVE_INFINITY;
  }
  return timestamp;
}

function maintenanceLogCreatedSortValue(createdAt) {
  const timestamp = Date.parse(String(createdAt || '').trim());
  return Number.isFinite(timestamp) ? timestamp : Number.NEGATIVE_INFINITY;
}

function compareMaintenanceLogsNewestFirst(logA, logB) {
  const dateA = Number.isFinite(logA?.timestamp)
    ? logA.timestamp
    : maintenanceLogDateSortValue(logA?.date);
  const dateB = Number.isFinite(logB?.timestamp)
    ? logB.timestamp
    : maintenanceLogDateSortValue(logB?.date);
  if (dateA !== dateB) return dateB - dateA;

  const createdA = Number.isFinite(logA?.createdTimestamp)
    ? logA.createdTimestamp
    : maintenanceLogCreatedSortValue(logA?.createdAt);
  const createdB = Number.isFinite(logB?.createdTimestamp)
    ? logB.createdTimestamp
    : maintenanceLogCreatedSortValue(logB?.createdAt);
  if (createdA !== createdB) return createdB - createdA;

  return Number(logB?.originalIndex ?? -1) - Number(logA?.originalIndex ?? -1);
}

function getLastAddedMaintenanceLog(asset) {
  return getMaintenanceLogRecords(asset)
    .map((record, originalIndex) => ({ ...record, originalIndex }))
    .sort(compareMaintenanceLogsNewestFirst)[0] || null;
}

function maintenanceMarkedStatus(log) {
  const record = normalizeMaintenanceLogRecord(log);
  const flaggedStatuses = new Set(['ooc', 'missing', 'untagged', 'degraded']);

  for (let index = record.changes.length - 1; index >= 0; index--) {
    const change = record.changes[index];
    const kind = String(change.kind || '').trim().toLowerCase();
    const action = String(change.action || '').trim().toLowerCase();
    if (action === 'marked' && flaggedStatuses.has(kind)) return kind;
  }

  const sourceKind = String(record.source?.kind || '').trim().toLowerCase();
  const bulkStatus = String(record.source?.bulkStatus || '').trim().toLowerCase();
  if (sourceKind === 'bulk_maintenance_fault' && flaggedStatuses.has(bulkStatus)) {
    return bulkStatus;
  }

  return '';
}

function getLastFlaggedMaintenanceLog(asset) {
  const records = getMaintenanceLogRecords(asset);
  for (let index = records.length - 1; index >= 0; index--) {
    const status = maintenanceMarkedStatus(records[index]);
    if (status) return { record: records[index], status };
  }
  return null;
}

function sortAssetsByLastAddedMaintenanceLog(assetsToSort) {
  return [...(assetsToSort || [])].sort((assetA, assetB) => {
    const latestA = getLastAddedMaintenanceLog(assetA);
    const latestB = getLastAddedMaintenanceLog(assetB);
    if (latestA && latestB) {
      const comparison = compareMaintenanceLogsNewestFirst(latestA, latestB);
      if (comparison) return comparison;
    } else if (latestA) return -1;
    else if (latestB) return 1;

    return assetMaintenanceDisplayId(assetA).localeCompare(
      assetMaintenanceDisplayId(assetB),
      undefined,
      { numeric: true, sensitivity: 'base' }
    );
  });
}

function getMaintenanceChangeLabels(logOrChanges) {
  const changes = Array.isArray(logOrChanges)
    ? logOrChanges.map(normalizeMaintenanceChange).filter(Boolean)
    : normalizeMaintenanceLogRecord(logOrChanges).changes;

  return changes.map(change => {
    if (change.kind === 'location') return `Location: ${change.value}`;
    if (change.kind === 'serial') return `Serial: ${change.value}`;
    if (change.kind === 'version') return `Version: ${change.value}`;
    if (change.kind === 'ooc') return change.action === 'marked' ? 'Marked OOC' : 'Cleared OOC';
    if (change.kind === 'missing') return change.action === 'marked' ? 'Marked Missing' : 'Cleared Missing';
    if (change.kind === 'untagged') return change.action === 'marked' ? 'Marked Untagged' : 'Cleared Untagged';
    if (change.kind === 'degraded') return change.action === 'marked' ? 'Marked Degraded' : 'Cleared Degraded';
    if (change.kind === 'decommissioned' || change.kind === 'disposed') return change.action === 'marked' ? 'Marked Decommissioned' : 'Cleared Decommissioned';
    return '';
  }).filter(Boolean);
}

function maintenanceChangeColour(label) {
  const changeLower = String(label || '').toLowerCase();
  if (changeLower.includes('cleared ooc') || changeLower.includes('clear ooc') || changeLower.includes('removed ooc') || changeLower.includes('unmark ooc')) return '#28a745';
  if (changeLower.includes('cleared missing') || changeLower.includes('clear missing') || changeLower.includes('removed missing') || changeLower.includes('unmark missing')) return '#28a745';
  if (changeLower.includes('cleared untagged') || changeLower.includes('clear untagged') || changeLower.includes('removed untagged') || changeLower.includes('unmark untagged')) return '#28a745';
  if (changeLower.includes('cleared degraded')) return '#28a745';
  if (changeLower.includes('cleared decommissioned') || changeLower.includes('cleared disposed')) return '#28a745';
  if (changeLower.includes('marked ooc') || changeLower.includes('mark ooc')) return '#dc3545';
  if (changeLower.includes('marked missing') || changeLower.includes('mark missing')) return '#fd7e14';
  if (changeLower.includes('marked untagged') || changeLower.includes('mark untagged')) return '#0e7490';
  if (changeLower.includes('marked degraded')) return '#856404';
  if (changeLower.includes('marked decommissioned') || changeLower.includes('marked disposed')) return '#6c757d';
  if (changeLower.includes('location:')) return '#17a2b8';
  if (changeLower.includes('serial:')) return '#6f42c1';
  if (changeLower.includes('version:')) return '#6f42c1';
  return '#667eea';
}

function maintenanceChangePdfHtml(label) {
  const color = maintenanceChangeColour(label);
  return `<span class="maintenance-change-pdf" style="display:block;margin-bottom:2px;color:${color};font-weight:700;-webkit-print-color-adjust:exact;print-color-adjust:exact;">${escapeHtml(label)}</span>`;
}

function getMaintenanceChangeValue(log, kind) {
  const record = normalizeMaintenanceLogRecord(log);
  const change = record.changes.find(item => item.kind === kind);
  return change ? (change.value || change.action || '') : '';
}

function maintenanceAssetSearchText(asset) {
  return [
    getAssetIdentifierForApi(asset), asset.id, asset.brand, asset.model, asset.description,
    assetTagSearchText(asset),
    asset.serial, asset.serialNumber, asset.serial2, asset.secondarySerial, asset.secondarySerialNumber,
    asset.version,
    asset.status, asset.location,
    ...getMaintenanceLogRecords(asset).map(log => `${log.type || ''} ${log.description || ''} ${maintenanceLogUserLabel(log)} ${log.date || ''}`)
  ].filter(Boolean).join(' ').toLowerCase();
}

function maintenanceActivitySearchText(asset, log) {
  const record = normalizeMaintenanceLogRecord(log);
  return [
    getAssetIdentifierForApi(asset), asset.id, asset.brand, asset.model,
    asset.description, asset.serial, asset.serialNumber, asset.serial2,
    asset.secondarySerial, asset.secondarySerialNumber, asset.version,
    record.type, record.description, maintenanceLogUserLabel(record), record.date,
    ...getMaintenanceChangeLabels(record),
    record.source?.containerId,
  ].filter(Boolean).join(' ').toLowerCase();
}

function maintenanceActivityEntries(assetList) {
  return (assetList || []).flatMap(asset =>
    getMaintenanceLogRecords(asset).map((log, originalIndex) => ({
      asset,
      log: { ...log, originalIndex },
    }))
  ).sort((entryA, entryB) => {
    const comparison = compareMaintenanceLogsNewestFirst(entryA.log, entryB.log);
    if (comparison) return comparison;
    return assetMaintenanceDisplayId(entryA.asset).localeCompare(
      assetMaintenanceDisplayId(entryB.asset),
      undefined,
      { numeric: true, sensitivity: 'base' }
    );
  });
}

function maintenanceAssetMatchesCondition(asset, condition) {
  if (!condition || condition === 'all') return true;
  if (condition === 'ooc') return Boolean(asset.isOOC || Number(asset.bulkOOCQuantity || 0) > 0);
  if (condition === 'missing') return Boolean(asset.isMissing || Number(asset.bulkMissingQuantity || 0) > 0);
  if (condition === 'untagged') return Boolean(asset.isUntagged);
  if (condition === 'degraded') return Boolean(asset.isDegraded || Number(asset.bulkDegradedQuantity || 0) > 0);
  if (condition === 'decommissioned') return Boolean(asset.isDisposed || asset.isDecommissioned);
  return true;
}

function renderMaintenanceFilterButtons() {
  const typeRoot = document.getElementById('maintenance-log-type-filters');
  if (typeRoot) {
    const typeCounts = assets.reduce((counts, asset) => {
      getMaintenanceLogRecords(asset).forEach(log => {
        const type = normalizeMaintenanceLogType(log.type);
        counts[type] = (counts[type] || 0) + 1;
      });
      return counts;
    }, {});
    const typeOptions = [
      ['all', 'All', '#0f766e', '#e9f6f2'],
      ...MAINTENANCE_LOG_TYPES.map(type => {
        const meta = maintenanceLogTypeMeta(type);
        return [type, meta.label, meta.color, meta.background];
      }),
    ];
    if (
      maintenanceLogTypeFilter === 'No history' ||
      (maintenanceLogTypeFilter !== 'all' && !(typeCounts[maintenanceLogTypeFilter] || 0))
    ) maintenanceLogTypeFilter = 'all';
    typeRoot.innerHTML = typeOptions.filter(([value]) => value === 'all' || (typeCounts[value] || 0) > 0).map(([value, label, color, background]) => {
      const count = value === 'all'
        ? Object.values(typeCounts).reduce((sum, valueCount) => sum + valueCount, 0)
        : (typeCounts[value] || 0);
      return `<button type="button" class="maintenance-filter-button${maintenanceLogTypeFilter === value ? ' active' : ''}" style="--filter-color:${color};--filter-bg:${background}" onclick="setMaintenanceLogTypeFilter('${escapeJs(value)}')">${escapeHtml(label)} ${count}</button>`;
    }).join('');
  }

  const conditionRoot = document.getElementById('maintenance-condition-filters');
  if (conditionRoot) {
    const options = [
      ['all', 'All', '#0f766e', '#e9f6f2'],
      ['ooc', 'OOC', '#a61b29', '#fdebed'],
      ['missing', 'Missing', '#596b78', '#edf0f2'],
      ['untagged', 'Untagged', '#0e7490', '#e7f7fa'],
      ['degraded', 'Degraded', '#8a5b08', '#fff3df'],
      ['decommissioned', 'Decommissioned', '#3f4d48', '#edf0f2']
    ];
    if (maintenanceConditionFilter !== 'all' && !maintenanceFlaggedAssets.some(asset => maintenanceAssetMatchesCondition(asset, maintenanceConditionFilter))) maintenanceConditionFilter = 'all';
    conditionRoot.innerHTML = options.filter(([value]) => value === 'all' || maintenanceFlaggedAssets.some(asset => maintenanceAssetMatchesCondition(asset, value))).map(([value, label, color, background]) => {
      const count = value === 'all' ? maintenanceFlaggedAssets.length : maintenanceFlaggedAssets.filter(asset => maintenanceAssetMatchesCondition(asset, value)).length;
      return `<button type="button" class="maintenance-filter-button${maintenanceConditionFilter === value ? ' active' : ''}" style="--filter-color:${color};--filter-bg:${background}" onclick="setMaintenanceConditionFilter('${value}')">${label} ${count}</button>`;
    }).join('');
  }
}

function applyMaintenanceRecentFilters() {
  const query = document.getElementById('maintenance-search')?.value.trim().toLowerCase() || '';
  displayMaintenanceAssets(assets, {
    query,
    logType: maintenanceLogTypeFilter,
  });
}

function setMaintenanceLogTypeFilter(type) {
  maintenanceLogTypeFilter = type || 'all';
  renderMaintenanceFilterButtons();
  applyMaintenanceRecentFilters();
}

function setMaintenanceConditionFilter(condition) {
  maintenanceConditionFilter = condition || 'all';
  renderMaintenanceFilterButtons();
  filterOOCAssets();
}

async function loadMaintenanceAssets() {
  const loadGeneration = ++assetPageLoadGeneration;
  try {
    const renderLoaded = loaded => {
      if (loadGeneration !== assetPageLoadGeneration) return;
      assets = loaded;
      maintenanceFlaggedAssets = getMaintenanceFlaggedAssets(assets);
      renderMaintenanceDashboardSummary(assets);
      renderMaintenanceFilterButtons();
      const activeTab = document.querySelector(".maintenance-tab.active");
      if (activeTab && activeTab.getAttribute('data-tab') === 'ooc') {
        filterOOCAssets();
      } else {
        applyMaintenanceRecentFilters();
      }
    };
    const assetLoad = await loadAssetPagesProgressively({
      pageSize: 100,
      onPage: renderLoaded,
      isCancelled: () => loadGeneration !== assetPageLoadGeneration
    });
    if (loadGeneration !== assetPageLoadGeneration) return;
    renderLoaded(assetLoad.first);
    assetLoad.completion.catch(error => {
      console.warn('Unable to load the remaining maintenance pages:', error);
    });
  } catch (error) {
    document.getElementById("maintenance-assets").innerHTML =
      '<p style="color: red; text-align: center;">Error loading assets</p>';
  }
}

function getMaintenanceFlaggedAssets(assetList) {
  return (assetList || []).filter(asset =>
    asset.isOOC || asset.isMissing || asset.isUntagged || asset.isDegraded || asset.isDisposed || asset.isDecommissioned ||
    (asset.isBulk && (
      Number(asset.bulkOOCQuantity || 0) > 0 ||
      Number(asset.bulkMissingQuantity || 0) > 0 ||
      Number(asset.bulkDegradedQuantity || 0) > 0
    ))
  );
}

function renderMaintenanceDashboardSummary(assetList) {
  const source = Array.isArray(assetList) ? assetList : [];
  const counts = inventoryConditionCounts(source);
  const flagged = getMaintenanceFlaggedAssets(source);
  const logEntries = source.reduce((sum, asset) => sum + getMaintenanceLogRecords(asset).length, 0);
  const items = [
    ['wrench', logEntries, 'Maintenance entries', '#1769aa', '#eaf3fb'],
    ['alert', flagged.length, 'Assets needing attention', '#b4760b', '#fff3df'],
    ['alert', counts.ooc, 'Out of commission', '#c53d49', '#fdebed'],
    ['box', counts.missing, 'Missing', '#596b78', '#edf0f2'],
    ['box', counts.untagged, 'Untagged', '#0e7490', '#e7f7fa'],
    ['wrench', counts.degraded, 'Degraded', '#b4760b', '#fff3df']
  ];
  const summary = document.getElementById('maintenance-dashboard-summary');
  if (summary) summary.innerHTML = items.map(([icon, value, label, color, bg]) => `
    <div class="maintenance-summary-item">
      <span class="maintenance-summary-mark" style="--summary-color:${color};--summary-bg:${bg}">${inventoryIcon(icon)}</span>
      <span><strong class="maintenance-summary-value">${value}</strong><span class="maintenance-summary-label">${label}</span></span>
    </div>
  `).join('');
  const recentCount = document.getElementById('maintenance-recent-count');
  const flaggedCount = document.getElementById('maintenance-flagged-count');
  const recentTab = document.querySelector('.maintenance-tab[data-tab="all"]');
  const flaggedTab = document.querySelector('.maintenance-tab[data-tab="ooc"]');
  if (recentTab && !recentCount) recentTab.innerHTML = `Recent activity <span id="maintenance-recent-count" class="maintenance-tab-count">${logEntries}</span>`;
  if (flaggedTab && !flaggedCount) flaggedTab.innerHTML = `Needs attention <span id="maintenance-flagged-count" class="maintenance-tab-count">${flagged.length}</span>`;
  const currentRecentCount = document.getElementById('maintenance-recent-count');
  const currentFlaggedCount = document.getElementById('maintenance-flagged-count');
  if (currentRecentCount) currentRecentCount.textContent = String(logEntries);
  if (currentFlaggedCount) currentFlaggedCount.textContent = String(flagged.length);
  [recentTab, flaggedTab].forEach(tab => { if (tab) tab.setAttribute('role', 'tab'); });
  const maintenanceSearch = document.getElementById('maintenance-search');
  if (maintenanceSearch) maintenanceSearch.placeholder = 'Search asset, serial, model, log or user';
  renderMaintenanceFilterButtons();
}

function maintenanceActivityRowHtml(asset, latestRecord = null) {
  const assetId = getAssetIdentifierForApi(asset);
  const displayId = assetMaintenanceDisplayId(asset);
  const latest = latestRecord || inventoryLatestMaintenance([asset]);
  const model = [asset.brand, asset.model].filter(Boolean).join(' ') || 'Unspecified model';
  const description = latest?.description || 'No maintenance history recorded';
  const location = asset.currentLocation || asset.location || 'Store';

  return `
    <div class="maintenance-activity-row" role="button" tabindex="0" onclick="viewMaintenanceLog('${escapeJs(assetId)}')" onkeydown="if(event.target===this&&(event.key==='Enter'||event.key===' ')){event.preventDefault();viewMaintenanceLog('${escapeJs(assetId)}')}" aria-label="View maintenance history for ${escapeHtmlAttr(displayId)}">
      <span><span class="maintenance-asset-id">${escapeHtml(displayId)}${asset.isBulk ? ' <span class="asset-badge status-available">Bulk</span>' : ''}</span><span class="maintenance-asset-model">${escapeHtml(model)}${asset.description ? ` · ${escapeHtml(asset.description)}` : ''}</span></span>
      <span class="maintenance-log-summary"><span class="maintenance-log-summary-top">${latest ? maintenanceLogTypeBadgeHtml(latest.type) : '<span class="asset-badge status-decommissioned">No history</span>'}<span class="maintenance-log-author">${latest?.user ? `by ${escapeHtml(maintenanceLogUserLabel(latest))}` : ''}</span></span><span class="maintenance-log-description">${maintenanceDescriptionHtml(description)}</span></span>
      <span>${assetFlagBadgesHtml(asset)}</span>
      <span class="maintenance-row-date">${escapeHtml(inventoryMaintenanceDateText(latest))}<span>${escapeHtml(location)}</span></span>
      <span class="maintenance-row-chevron"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg></span>
    </div>
  `;
}

function displayMaintenanceAssets(assetsToShow, options = {}) {
  const container = document.getElementById("maintenance-assets");
  if (!container) return;

  const query = String(options.query || '').trim().toLowerCase();
  const logType = String(options.logType || 'all');
  const activityEntries = maintenanceActivityEntries(assetsToShow).filter(entry => {
    if (logType !== 'all' && normalizeMaintenanceLogType(entry.log.type) !== logType) {
      return false;
    }
    return !query || maintenanceActivitySearchText(entry.asset, entry.log).includes(query);
  });

  if (activityEntries.length === 0) {
    destroyVirtualTable('maintenance-all');
    container.innerHTML = '<div class="maintenance-empty">No maintenance activity matches this search.</div>';
    return;
  }

  destroyVirtualTable('maintenance-all');
  const visibleEntries = activityEntries.slice(0, 250);
  container.innerHTML = `
    <div class="maintenance-list-header"><span>Asset</span><span>Maintenance log</span><span>Condition</span><span>Date / location</span><span></span></div>
    <div class="maintenance-activity-list">${visibleEntries.map(entry => maintenanceActivityRowHtml(entry.asset, entry.log)).join('')}</div>
    ${activityEntries.length > visibleEntries.length ? `<div style="padding:8px 2px;color:#64748b;font-size:9px">Showing the 250 most recent logs. Search to find older activity.</div>` : ''}
  `;
}

