async function deleteMaintenanceLog(assetId, logIndex, logId) {
  if (!isAdminUser()) {
    showNotification('error', 'Admin privileges required to delete maintenance logs');
    return;
  }

  // Show custom confirmation dialog
  const shouldDelete = await showCustomConfirm(
    'Delete Maintenance Log',
    'Are you sure you want to delete this maintenance log entry? Attached media will be deleted too. This action cannot be undone and will recalculate the asset status.'
  );

  if (!shouldDelete) {
    return;
  }

  try {
    const encodedAssetId = encodeURIComponent(assetId);
    const url = `/api/assets/${encodedAssetId}/maintenance-log/${logIndex}`;

    const response = await apiCall(url, 'DELETE');

    if (response && response.success) {
      showNotification('success', 'Maintenance log deleted and asset status updated');

      try {
        const [updatedAsset] = await refreshInventoryAssetsInPlace([assetId]);
        if (updatedAsset) {
          document.getElementById('editMaintenanceLogModal')?.remove();
          showMaintenanceLogModal(updatedAsset);
        }
      } catch (reloadError) {
        console.warn('Could not reload asset data:', reloadError);
        closeMaintenanceLogModal();
        showNotification('info', 'The log was deleted, but the updated asset could not be displayed');
      }
    } else {
      console.error('API returned error or no response:', response);
      showNotification('error', (response && response.message) || 'Failed to delete maintenance log');
    }

  } catch (error) {
    console.error('Error deleting maintenance log:', error);
    showNotification('error', `Failed to delete maintenance log: ${error.message}`);
  }
}

function removeMaintenanceMediaFromLocalAssets(mediaId) {
  const normalizedId = String(mediaId || '');
  (assets || []).forEach(asset => {
    const records = getMaintenanceLogRecords(asset);
    let changed = false;
    records.forEach(record => {
      const retained = normalizeMaintenanceMedia(record.media).filter(item => item.id !== normalizedId);
      if (retained.length !== record.media.length) {
        record.media = retained;
        changed = true;
      }
    });
    if (changed) asset.maintenanceLogRecords = records;
  });
}

function removeMaintenanceMediaElements(mediaId) {
  document.querySelectorAll('[data-maintenance-media-item]').forEach(item => {
    if (item.dataset.maintenanceMediaId !== String(mediaId || '')) return;
    const group = item.parentElement;
    item.remove();
    if (group && !group.querySelector('[data-maintenance-media-item]')) {
      group.insertAdjacentHTML(
        'beforeend',
        '<span data-maintenance-media-empty style="color:#6c757d;font-size:13px;">No media attached</span>'
      );
    }
  });
}

async function deleteMaintenanceMedia(mediaId, assetId = '', logIndex = -1, triggerButton = null) {
  if (!isAdminUser()) {
    showNotification('error', 'Admin privileges required to remove maintenance media');
    return;
  }

  const shouldDelete = await showCustomConfirm(
    'Remove Maintenance Media',
    'Are you sure you want to permanently delete this photo or video? This action cannot be undone.'
  );
  if (!shouldDelete) return;

  const originalButtonText = triggerButton?.textContent || '';
  if (triggerButton) {
    triggerButton.disabled = true;
    triggerButton.setAttribute('aria-busy', 'true');
    triggerButton.textContent = '...';
  }

  try {
    await apiCall(`/api/maintenance-media/${encodeURIComponent(mediaId)}`, 'DELETE');
    removeMaintenanceMediaFromLocalAssets(mediaId);
    removeMaintenanceMediaElements(mediaId);
    showNotification('success', 'Maintenance media permanently deleted');
  } catch (error) {
    showNotification('error', `Failed to remove maintenance media: ${error.message}`);
  } finally {
    if (triggerButton?.isConnected) {
      triggerButton.disabled = false;
      triggerButton.removeAttribute('aria-busy');
      triggerButton.textContent = originalButtonText;
    }
  }
}

function showCustomConfirm(titleOrMessage, maybeMessage, options = {}) {
  const hasSeparateMessage = typeof maybeMessage === 'string';
  const title = hasSeparateMessage ? titleOrMessage : (options.title || 'Confirm Action');
  const message = hasSeparateMessage ? maybeMessage : titleOrMessage;
  const destructive = /delete|remove/i.test(`${title} ${message}`);

  return showAppConfirm({
    title,
    message,
    confirmText: options.confirmText || (destructive ? 'Delete' : 'Confirm'),
    cancelText: options.cancelText || 'Cancel',
    variant: options.variant || (destructive ? 'danger' : 'warning'),
  });
}

function deleteMaintenanceLogFromModal(assetId, logIndex, logId) {
  // Close the edit modal first
  const editModal = document.getElementById('editMaintenanceLogModal');
  if (editModal) {
    editModal.remove();
  }

  // Then call the delete function
  deleteMaintenanceLog(assetId, logIndex, logId);
}

